module.exports = {"/index.html":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Reclaim — Campus Lost &amp; Found System</title>\n  <link rel=\"stylesheet\" href=\"/styles.css\" />\n</head>\n<body>\n\n  <!-- ==================== 1. UNIFIED LOGIN SCREEN (NO REGISTER PAGE) ==================== -->\n  <section id=\"login-screen\" class=\"login-screen\">\n    <div class=\"login-container\">\n      <!-- Left Branding Panel -->\n      <div class=\"login-hero\">\n        <div class=\"brand-badge\">\n          <span class=\"brand-icon\">◈</span>\n          <span>UNIVERSITY VERIFIED PLATFORM</span>\n        </div>\n        <h1 class=\"hero-logo-title\">reclaim<span>.</span></h1>\n        <p class=\"hero-subtitle\">\n          The centralized, privacy-first Campus Lost &amp; Found platform powered by automated matching and administrator-verified ownership claims.\n        </p>\n\n        <div class=\"hero-features\">\n          <div class=\"hero-feature-item\">\n            <div class=\"feature-icon\">⚡</div>\n            <div>\n              <h4>&lt; 3s Automated Matching Engine</h4>\n              <p>Instantly cross-references lost and found reports across campus buildings, categories, colors, and brands.</p>\n            </div>\n          </div>\n          <div class=\"hero-feature-item\">\n            <div class=\"feature-icon\">🔒</div>\n            <div>\n              <h4>Privacy Blur &amp; Identity Protection</h4>\n              <p>Found item photos are blurred for public viewers to prevent false claims, and personal contact info is never exposed.</p>\n            </div>\n          </div>\n          <div class=\"hero-feature-item\">\n            <div class=\"feature-icon\">🛡️</div>\n            <div>\n              <h4>Admin Verification &amp; SQLite Persistence</h4>\n              <p>Side-by-side visual proof inspection, additional proof requests, and physical handover tracking.</p>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"hero-footer-pill\">\n          <span class=\"status-dot\"></span>\n          <span>SQLite Engine Active • Localhost Prototype</span>\n        </div>\n      </div>\n\n      <!-- Right Single Login Form Panel -->\n      <div class=\"login-card\">\n        <div class=\"login-card-header\">\n          <h2>Sign In to Reclaim</h2>\n          <p>\n            Enter any username and password. <strong>If the account doesn't exist yet, Reclaim automatically creates and remembers it in SQLite.</strong>\n          </p>\n        </div>\n\n        <form id=\"login-form\" class=\"login-form\">\n          <div class=\"form-group\">\n            <label for=\"login-username\">Campus Username</label>\n            <input\n              type=\"text\"\n              id=\"login-username\"\n              placeholder=\"e.g. ahmed, khalid, admin, or your name\"\n              required\n              autocomplete=\"username\"\n            />\n          </div>\n\n          <div class=\"form-group\">\n            <label for=\"login-password\">Password</label>\n            <input\n              type=\"password\"\n              id=\"login-password\"\n              placeholder=\"Enter password (saved automatically)\"\n              required\n              autocomplete=\"current-password\"\n            />\n          </div>\n\n          <div id=\"login-error\" class=\"alert-box alert-error hidden\"></div>\n\n          <button type=\"submit\" class=\"btn btn-primary btn-block btn-lg\">\n            Continue to Reclaim →\n          </button>\n        </form>\n\n        <div class=\"quick-demo-login\">\n          <span class=\"quick-demo-label\">Presentation 1-Click Fill:</span>\n          <div class=\"quick-demo-chips\">\n            <button type=\"button\" class=\"demo-chip\" onclick=\"quickFillLogin('ahmed', '1234')\">\n              🎓 <strong>ahmed</strong> (Lost Owner)\n            </button>\n            <button type=\"button\" class=\"demo-chip\" onclick=\"quickFillLogin('khalid', '1234')\">\n              🔍 <strong>khalid</strong> (Finder)\n            </button>\n            <button type=\"button\" class=\"demo-chip demo-chip-admin\" onclick=\"quickFillLogin('admin', 'admin')\">\n              🛡️ <strong>admin</strong> (Administrator)\n            </button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ==================== 2. MAIN APPLICATION SHELL ==================== -->\n  <div id=\"app-shell\" class=\"app-shell hidden\">\n    <!-- Top Header Navigation -->\n    <header class=\"top-navbar\">\n      <div class=\"nav-left\">\n        <div class=\"app-logo\" onclick=\"switchView('home')\">\n          <span class=\"logo-mark\">◈</span>\n          <span class=\"logo-text\">reclaim<span class=\"logo-dot\">.</span></span>\n          <span class=\"campus-tag\">CAMPUS L&amp;F</span>\n        </div>\n\n        <nav class=\"main-nav\">\n          <button class=\"nav-btn active\" data-view=\"home\" onclick=\"switchView('home')\">\n            🏠 Home\n          </button>\n          <button class=\"nav-btn\" data-view=\"browse\" onclick=\"switchView('browse')\">\n            🔍 Search &amp; Browse\n          </button>\n          <button class=\"nav-btn\" data-view=\"report\" onclick=\"switchView('report')\">\n            ➕ Report Item\n          </button>\n          <button class=\"nav-btn\" data-view=\"claims\" onclick=\"switchView('claims')\">\n            📋 Matches &amp; Claims\n            <span id=\"nav-claims-badge\" class=\"nav-badge hidden\">0</span>\n          </button>\n          <button id=\"nav-admin-tab\" class=\"nav-btn nav-btn-admin hidden\" data-view=\"admin\" onclick=\"switchView('admin')\">\n            🛡️ Admin Workspace\n            <span id=\"nav-admin-badge\" class=\"nav-badge nav-badge-warn\">0</span>\n          </button>\n        </nav>\n      </div>\n\n      <div class=\"nav-right\">\n        <!-- Notification Bell -->\n        <button class=\"icon-btn\" onclick=\"toggleNotificationsDrawer()\" title=\"System Notifications\">\n          🔔\n          <span id=\"notif-unread-badge\" class=\"notif-badge hidden\">0</span>\n        </button>\n\n        <!-- Current User Pill -->\n        <div class=\"user-profile-pill\">\n          <div class=\"user-avatar\" id=\"header-user-avatar\">A</div>\n          <div class=\"user-meta\">\n            <span id=\"header-username\" class=\"user-name\">@ahmed</span>\n            <span id=\"header-user-role\" class=\"user-role-tag\">Student</span>\n          </div>\n        </div>\n\n        <button class=\"btn btn-outline btn-sm\" onclick=\"handleLogout()\">\n          Sign Out\n        </button>\n      </div>\n    </header>\n\n    <!-- Main Content Viewport -->\n    <main class=\"main-content\">\n\n      <!-- VIEW 1: HOME DASHBOARD -->\n      <section id=\"view-home\" class=\"view-section\">\n        <div class=\"hero-banner\">\n          <div class=\"hero-banner-text\">\n            <div class=\"hero-pill\">✨ Main Scenario &amp; Live Campus Feed</div>\n            <h1 id=\"welcome-headline\">Welcome back to Reclaim</h1>\n            <p>\n              Lost something after a lecture or found an unattended item on campus? Report it in seconds—our automated matching engine scans complementary reports in under 3 seconds while protecting student privacy.\n            </p>\n            <div class=\"hero-actions\">\n              <button class=\"btn btn-light-solid\" onclick=\"openReportForm('LOST')\">\n                📢 Report Lost Item\n              </button>\n              <button class=\"btn btn-glass\" onclick=\"openReportForm('FOUND')\">\n                📦 Report Found Item\n              </button>\n              <button class=\"btn btn-glass\" onclick=\"switchView('browse')\">\n                🔎 Search Campus Items\n              </button>\n            </div>\n          </div>\n\n          <div class=\"hero-stats-grid\">\n            <div class=\"stat-card\">\n              <span class=\"stat-value\" id=\"stat-total-reports\">0</span>\n              <span class=\"stat-label\">Active Campus Reports</span>\n            </div>\n            <div class=\"stat-card\">\n              <span class=\"stat-value\" id=\"stat-total-matches\">0</span>\n              <span class=\"stat-label\">Auto-Matches Suggested</span>\n            </div>\n            <div class=\"stat-card\">\n              <span class=\"stat-value\" id=\"stat-match-speed\">1.1 ms</span>\n              <span class=\"stat-label\">Match Engine Speed (&lt;3s NFR)</span>\n            </div>\n            <div class=\"stat-card\">\n              <span class=\"stat-value\" id=\"stat-resolved-cases\">0</span>\n              <span class=\"stat-label\">Items Verified &amp; Returned</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- Automated Suggested Matches Banner -->\n        <div class=\"section-block\">\n          <div class=\"section-header\">\n            <div>\n              <h2>⚡ Automated Match Suggestions</h2>\n              <p>Real-time matches discovered by comparing Category, Building Location, Color, Brand, and Keywords.</p>\n            </div>\n            <button class=\"btn btn-outline btn-sm\" onclick=\"switchView('claims')\">\n              View All Matches &amp; Claims →\n            </button>\n          </div>\n          <div id=\"home-matches-container\" class=\"matches-grid\"></div>\n        </div>\n\n        <!-- Recent Campus Reports -->\n        <div class=\"section-block\">\n          <div class=\"section-header\">\n            <div>\n              <h2>📍 Recent Campus Reports</h2>\n              <p>Note: Found item photos are automatically blurred for students to prevent fraudulent claims.</p>\n            </div>\n            <button class=\"btn btn-outline btn-sm\" onclick=\"switchView('browse')\">\n              Open Search &amp; Filters →\n            </button>\n          </div>\n          <div id=\"home-reports-container\" class=\"reports-grid\"></div>\n        </div>\n      </section>\n\n      <!-- VIEW 2: SEARCH & BROWSE ITEMS (Use Case 3 / BPMN Fig. 3) -->\n      <section id=\"view-browse\" class=\"view-section hidden\">\n        <div class=\"page-title-bar\">\n          <div>\n            <h2>🔍 Search &amp; Filter Campus Listings</h2>\n            <p>Search reported Lost &amp; Found items across campus buildings. Found item photos use Privacy Blur protection.</p>\n          </div>\n          <div class=\"page-title-actions\">\n            <button class=\"btn btn-primary\" onclick=\"openReportForm('LOST')\">+ Report Lost</button>\n            <button class=\"btn btn-secondary\" onclick=\"openReportForm('FOUND')\">+ Report Found</button>\n          </div>\n        </div>\n\n        <!-- Filter Bar -->\n        <div class=\"filter-bar\">\n          <div class=\"filter-group filter-search\">\n            <label>Keyword Search</label>\n            <input type=\"text\" id=\"filter-q\" placeholder=\"Search charger, calculator, bottle, Dell...\" oninput=\"applySearchFilters()\" />\n          </div>\n          <div class=\"filter-group\">\n            <label>Report Type</label>\n            <select id=\"filter-type\" onchange=\"applySearchFilters()\">\n              <option value=\"ALL\">All Types (Lost &amp; Found)</option>\n              <option value=\"FOUND\">Found Items Only</option>\n              <option value=\"LOST\">Lost Items Only</option>\n            </select>\n          </div>\n          <div class=\"filter-group\">\n            <label>Category</label>\n            <select id=\"filter-category\" onchange=\"applySearchFilters()\">\n              <option value=\"ALL\">All Categories</option>\n              <option value=\"Electronics\">Electronics</option>\n              <option value=\"ID & Cards\">ID &amp; Cards</option>\n              <option value=\"Bottles & Accessories\">Bottles &amp; Accessories</option>\n              <option value=\"Books & Notes\">Books &amp; Notes</option>\n              <option value=\"Keys & Wallets\">Keys &amp; Wallets</option>\n            </select>\n          </div>\n          <div class=\"filter-group\">\n            <label>Campus Building</label>\n            <select id=\"filter-location\" onchange=\"applySearchFilters()\">\n              <option value=\"ALL\">All Campus Buildings</option>\n              <option value=\"Engineering Building\">Engineering Building</option>\n              <option value=\"Main Library\">Main Library</option>\n              <option value=\"Student Center\">Student Center</option>\n              <option value=\"Science Complex\">Science Complex</option>\n              <option value=\"Cafeteria\">Cafeteria</option>\n              <option value=\"Sports Hall\">Sports Hall</option>\n            </select>\n          </div>\n          <div class=\"filter-group\">\n            <label>Color</label>\n            <select id=\"filter-color\" onchange=\"applySearchFilters()\">\n              <option value=\"ALL\">All Colors</option>\n              <option value=\"Black\">Black</option>\n              <option value=\"Blue\">Blue</option>\n              <option value=\"White\">White</option>\n              <option value=\"Silver\">Silver</option>\n              <option value=\"Purple\">Purple</option>\n              <option value=\"Red\">Red</option>\n            </select>\n          </div>\n          <div class=\"filter-group filter-reset\">\n            <label>&nbsp;</label>\n            <button class=\"btn btn-outline\" onclick=\"resetSearchFilters()\">Reset</button>\n          </div>\n        </div>\n\n        <div id=\"browse-reports-container\" class=\"reports-grid\"></div>\n      </section>\n\n      <!-- VIEW 3: REPORT LOST OR FOUND ITEM (Use Case 2 & 3 / BPMN Fig. 2 & 3) -->\n      <section id=\"view-report\" class=\"view-section hidden\">\n        <div class=\"form-card-wrapper\">\n          <div class=\"report-type-switcher\">\n            <button type=\"button\" id=\"tab-btn-lost\" class=\"type-switch-btn active-lost\" onclick=\"setReportFormType('LOST')\">\n              📢 Report a Lost Item\n              <span>I lost something on campus</span>\n            </button>\n            <button type=\"button\" id=\"tab-btn-found\" class=\"type-switch-btn\" onclick=\"setReportFormType('FOUND')\">\n              📦 Report a Found Item\n              <span>I found an item &amp; will hand it to Admin</span>\n            </button>\n          </div>\n\n          <form id=\"create-report-form\" class=\"report-form\">\n            <input type=\"hidden\" id=\"report-type-input\" value=\"LOST\" />\n\n            <div class=\"form-banner-info\" id=\"report-form-banner\">\n              <strong>Lost Item Report:</strong> Provide accurate details and an old photo if available. Our automated matching engine will scan existing Found reports in &lt; 3 seconds.\n            </div>\n\n            <!-- 1-Click Scenario Auto-Fill Bar for Live Presentation -->\n            <div class=\"preset-autofill-bar\">\n              <span>⚡ Quick Presentation Auto-Fill:</span>\n              <button type=\"button\" class=\"btn-chip\" onclick=\"autofillAhmedLostCharger()\">\n                Fill Ahmed's Lost Black Charger\n              </button>\n              <button type=\"button\" class=\"btn-chip\" onclick=\"autofillKhalidFoundCharger()\">\n                Fill Khalid's Found Black Charger\n              </button>\n            </div>\n\n            <div class=\"form-grid-2\">\n              <div class=\"form-group\">\n                <label>Item Title *</label>\n                <input type=\"text\" id=\"rep-title\" placeholder=\"e.g. Black Laptop Charger (65W USB-C)\" required />\n              </div>\n\n              <div class=\"form-group\">\n                <label>Category *</label>\n                <select id=\"rep-category\" required>\n                  <option value=\"Electronics\">Electronics</option>\n                  <option value=\"ID & Cards\">ID &amp; Cards</option>\n                  <option value=\"Bottles & Accessories\">Bottles &amp; Accessories</option>\n                  <option value=\"Books & Notes\">Books &amp; Notes</option>\n                  <option value=\"Keys & Wallets\">Keys &amp; Wallets</option>\n                </select>\n              </div>\n\n              <div class=\"form-group\">\n                <label>Primary Color *</label>\n                <select id=\"rep-color\" required>\n                  <option value=\"Black\">Black</option>\n                  <option value=\"Blue\">Blue</option>\n                  <option value=\"White\">White</option>\n                  <option value=\"Silver\">Silver</option>\n                  <option value=\"Purple\">Purple</option>\n                  <option value=\"Red\">Red</option>\n                </select>\n              </div>\n\n              <div class=\"form-group\">\n                <label>Brand / Make</label>\n                <input type=\"text\" id=\"rep-brand\" placeholder=\"e.g. Dell, Apple, Casio, HydroFlask\" />\n              </div>\n\n              <div class=\"form-group\">\n                <label>Campus Building / Location *</label>\n                <select id=\"rep-location\" required>\n                  <option value=\"Engineering Building\">Engineering Building</option>\n                  <option value=\"Main Library\">Main Library</option>\n                  <option value=\"Student Center\">Student Center</option>\n                  <option value=\"Science Complex\">Science Complex</option>\n                  <option value=\"Cafeteria\">Cafeteria</option>\n                  <option value=\"Sports Hall\">Sports Hall</option>\n                </select>\n              </div>\n\n              <div class=\"form-group\">\n                <label>Date &amp; Approximate Time *</label>\n                <input type=\"text\" id=\"rep-date\" value=\"Today, 10:30 AM\" required />\n              </div>\n            </div>\n\n            <div class=\"form-group\">\n              <label>General Description *</label>\n              <textarea id=\"rep-description\" rows=\"3\" placeholder=\"Describe where and how the item was lost or found...\" required></textarea>\n            </div>\n\n            <div class=\"form-group\">\n              <label>Unique Identifiers / Distinguishing Marks (Serial #, Stickers, Scratches)</label>\n              <input\n                type=\"text\"\n                id=\"rep-marks\"\n                placeholder=\"e.g. Blue velcro cable strap, Serial CN-065W-AH92 (Hidden from public on Found items)\"\n              />\n            </div>\n\n            <!-- BPMN Fig. 2 Physical Item Handover Checkbox (Only for FOUND items) -->\n            <div id=\"found-handover-box\" class=\"handover-checkbox-box hidden\">\n              <label class=\"checkbox-label\">\n                <input type=\"checkbox\" id=\"rep-handed\" checked />\n                <span>\n                  <strong>BPMN Fig. 2 Requirement:</strong> I confirm that I am handing over the physical item to the Campus Lost &amp; Found Administrator Office.\n                </span>\n              </label>\n            </div>\n\n            <!-- NFR Image Upload & Automatic <3MB Compression -->\n            <div class=\"form-group\">\n              <label>Item Photo (NFR: Auto-Compressed &le; 3.0 MB; Blurred automatically if Found Item)</label>\n              <div class=\"photo-upload-zone\">\n                <div class=\"photo-upload-controls\">\n                  <input type=\"file\" id=\"rep-file-input\" accept=\"image/*\" onchange=\"handleImageUpload(event, 'report')\" />\n                  <div class=\"preset-photo-selector\">\n                    <span>Or choose sample photo:</span>\n                    <button type=\"button\" class=\"btn-chip\" onclick=\"selectPresetPhoto('charger_lost', 'report')\">🔌 Charger (Owner)</button>\n                    <button type=\"button\" class=\"btn-chip\" onclick=\"selectPresetPhoto('charger_found', 'report')\">🔌 Charger (Found)</button>\n                    <button type=\"button\" class=\"btn-chip\" onclick=\"selectPresetPhoto('hydroflask', 'report')\">🧴 Water Bottle</button>\n                    <button type=\"button\" class=\"btn-chip\" onclick=\"selectPresetPhoto('calculator', 'report')\">🧮 Calculator</button>\n                    <button type=\"button\" class=\"btn-chip\" onclick=\"selectPresetPhoto('airpods', 'report')\">🎧 AirPods</button>\n                  </div>\n                  <div id=\"compression-telemetry\" class=\"compression-badge\">\n                    ✅ NFR Image Compression Ready: <strong>192.4 KB</strong> / 3,072 KB max limit\n                  </div>\n                </div>\n                <div class=\"photo-preview-box\">\n                  <img id=\"rep-photo-preview\" src=\"\" alt=\"Preview\" />\n                </div>\n              </div>\n            </div>\n\n            <div class=\"form-submit-row\">\n              <button type=\"submit\" class=\"btn btn-primary btn-lg\">\n                Submit Report &amp; Run Auto-Matcher →\n              </button>\n            </div>\n          </form>\n        </div>\n      </section>\n\n      <!-- VIEW 4: MATCHES & OWNERSHIP CLAIMS (Use Case 1 / BPMN Fig. 1 & Fig. 5) -->\n      <section id=\"view-claims\" class=\"view-section hidden\">\n        <div class=\"section-block\">\n          <div class=\"section-header\">\n            <div>\n              <h2>⚡ Suggested Matches for Your Reports</h2>\n              <p>Click \"Submit Ownership Claim\" on any matching Found item to provide proof of ownership to the Administrator.</p>\n            </div>\n          </div>\n          <div id=\"claims-view-matches\" class=\"matches-grid\"></div>\n        </div>\n\n        <div class=\"section-block\">\n          <div class=\"section-header\">\n            <div>\n              <h2>📋 Ownership Claims &amp; Verification Status</h2>\n              <p>Track your claims from <strong>Pending</strong> &rarr; <strong>More Proof Requested / Approved</strong> &rarr; <strong>Confirm Item Receipt</strong> &rarr; <strong>Returned &amp; Resolved</strong>.</p>\n            </div>\n          </div>\n          <div id=\"student-claims-container\" class=\"claims-list\"></div>\n        </div>\n      </section>\n\n      <!-- VIEW 5: DEDICATED ADMIN WORKSPACE (When logged in as Admin) -->\n      <section id=\"view-admin\" class=\"view-section hidden\">\n        <div class=\"admin-workspace-banner\">\n          <div>\n            <span class=\"admin-pill\">🛡️ ROLE-BASED ACCESS CONTROL: ADMINISTRATOR</span>\n            <h2>Lost &amp; Found Administrator Command Center</h2>\n            <p>Review pending ownership claims side-by-side with unblurred photos, request more proof, log physical handovers (BPMN Fig. 5), and moderate flagged reports (BPMN Fig. 4).</p>\n          </div>\n          <button class=\"btn btn-devops-trigger\" onclick=\"toggleDevOpsModal(true)\">\n            ⚡ Open Full Dark-Blue DevOps Overlay\n          </button>\n        </div>\n\n        <div class=\"section-block\">\n          <h3>1. Pending &amp; Active Ownership Claims (BPMN Fig. 1 &amp; Fig. 5)</h3>\n          <div id=\"admin-page-claims-list\" class=\"claims-list\"></div>\n        </div>\n\n        <div class=\"section-block\">\n          <h3>2. Flagged Suspicious / Duplicate Reports (BPMN Fig. 4)</h3>\n          <div id=\"admin-page-suspicious-list\" class=\"reports-grid\"></div>\n        </div>\n      </section>\n\n    </main>\n  </div>\n\n  <!-- ==================== 3. SUBMIT OWNERSHIP CLAIM MODAL ==================== -->\n  <div id=\"claim-modal\" class=\"modal-backdrop hidden\">\n    <div class=\"modal-card\">\n      <div class=\"modal-header\">\n        <div>\n          <h3>🛡️ Submit Ownership Claim (Use Case 1)</h3>\n          <p id=\"claim-modal-subtitle\">Provide proof of ownership so the Administrator can verify and release your item.</p>\n        </div>\n        <button class=\"close-btn\" onclick=\"closeClaimModal()\">✕</button>\n      </div>\n\n      <form id=\"submit-claim-form\" class=\"modal-body\">\n        <input type=\"hidden\" id=\"claim-found-report-id\" />\n        <input type=\"hidden\" id=\"claim-lost-report-id\" />\n\n        <div class=\"preset-autofill-bar\">\n          <span>⚡ Presentation Helper:</span>\n          <button type=\"button\" class=\"btn-chip\" onclick=\"autofillAhmedClaimProof()\">\n            Auto-Fill Ahmed's Charger Proof (Serial # + Blue Strap Photo)\n          </button>\n        </div>\n\n        <div class=\"form-group\">\n          <label>Proof of Ownership Description (Serial Number, Receipts, Distinguishing Marks) *</label>\n          <textarea\n            id=\"claim-proof-text\"\n            rows=\"4\"\n            placeholder=\"Describe unique identifiers that prove this item belongs to you (e.g. Serial number CN-065W-AH92, blue velcro strap, receipt details)...\"\n            required\n          ></textarea>\n        </div>\n\n        <div class=\"form-group\">\n          <label>Upload Visual Proof Photo (Receipt, Old Photo, or Serial Tag)</label>\n          <div class=\"photo-upload-zone compact\">\n            <div class=\"photo-upload-controls\">\n              <input type=\"file\" accept=\"image/*\" onchange=\"handleImageUpload(event, 'claim')\" />\n              <div class=\"preset-photo-selector\">\n                <button type=\"button\" class=\"btn-chip\" onclick=\"selectPresetPhoto('charger_proof', 'claim')\">\n                  📷 Use Ahmed's Serial # Proof Photo\n                </button>\n                <button type=\"button\" class=\"btn-chip\" onclick=\"selectPresetPhoto('charger_lost', 'claim')\">\n                  📷 Use Original Charger Photo\n                </button>\n              </div>\n            </div>\n            <div class=\"photo-preview-box small\">\n              <img id=\"claim-photo-preview\" src=\"\" alt=\"Proof Preview\" />\n            </div>\n          </div>\n        </div>\n\n        <div class=\"modal-footer\">\n          <button type=\"button\" class=\"btn btn-outline\" onclick=\"closeClaimModal()\">Cancel</button>\n          <button type=\"submit\" class=\"btn btn-primary\">Submit Claim (Status &rarr; Pending)</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- ==================== 4. SUBMIT ADDITIONAL PROOF MODAL (BPMN Fig. 1 Loop) ==================== -->\n  <div id=\"more-proof-modal\" class=\"modal-backdrop hidden\">\n    <div class=\"modal-card\">\n      <div class=\"modal-header\">\n        <div>\n          <h3>🔎 Provide Additional Proof (BPMN Fig. 1)</h3>\n          <p>The Administrator requested additional proof before approving your ownership claim.</p>\n        </div>\n        <button class=\"close-btn\" onclick=\"closeMoreProofModal()\">✕</button>\n      </div>\n      <form id=\"more-proof-form\" class=\"modal-body\">\n        <input type=\"hidden\" id=\"more-proof-claim-id\" />\n        <div id=\"more-proof-admin-prompt\" class=\"alert-box alert-warn\"></div>\n\n        <div class=\"form-group\">\n          <label>Additional Proof Details / Serial Confirmation *</label>\n          <textarea\n            id=\"more-proof-text\"\n            rows=\"3\"\n            placeholder=\"Enter the additional details requested by the Administrator...\"\n            required\n          >Here is the exact purchase invoice #INV-99281 and close-up photo of the serial tag CN-065W-AH92 on the adapter brick.</textarea>\n        </div>\n\n        <div class=\"modal-footer\">\n          <button type=\"button\" class=\"btn btn-outline\" onclick=\"closeMoreProofModal()\">Cancel</button>\n          <button type=\"submit\" class=\"btn btn-primary\">Resubmit Proof to Administrator →</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- ==================== 5. NOTIFICATIONS SLIDE-OVER DRAWER ==================== -->\n  <div id=\"notifications-drawer\" class=\"notif-drawer hidden\">\n    <div class=\"notif-drawer-header\">\n      <div>\n        <h3>🔔 System Notifications</h3>\n        <span class=\"notif-sub\">Privacy-protected real-time alerts</span>\n      </div>\n      <div class=\"notif-header-actions\">\n        <button class=\"btn-link\" onclick=\"markAllNotificationsRead()\">Mark all read</button>\n        <button class=\"close-btn\" onclick=\"toggleNotificationsDrawer(false)\">✕</button>\n      </div>\n    </div>\n    <div id=\"notifications-list\" class=\"notif-drawer-body\"></div>\n  </div>\n\n  <!-- ==================== 6. FLOATING BOTTOM-RIGHT DEVOPS / ADMIN BUTTON ==================== -->\n  <button id=\"devops-floating-btn\" class=\"devops-fab\" onclick=\"toggleDevOpsModal()\">\n    <span class=\"devops-fab-pulse\"></span>\n    <span class=\"devops-fab-icon\">⚡</span>\n    <div class=\"devops-fab-text\">\n      <strong>DevOps / Admin</strong>\n      <span>Control Panel</span>\n    </div>\n    <span id=\"devops-fab-badge\" class=\"devops-fab-badge\">1</span>\n  </button>\n\n  <!-- ==================== 7. COOL DARK-BLUE TINTED DEVOPS & ADMIN CONSOLE ==================== -->\n  <div id=\"devops-overlay\" class=\"devops-overlay hidden\">\n    <div class=\"devops-console\">\n      <!-- Console Top Header -->\n      <div class=\"devops-header\">\n        <div class=\"devops-title-group\">\n          <span class=\"devops-chip\">DARK-BLUE DEVOPS &amp; ADMIN ENGINE</span>\n          <h2>⚡ Reclaim DevOps &amp; Administrator Console</h2>\n          <p>Inspect SQLite state, switch active user personas in 1 click, verify claims (request more proof / approve / mark returned), and moderate reports.</p>\n        </div>\n        <button class=\"devops-close-btn\" onclick=\"toggleDevOpsModal(false)\">✕ Close Console</button>\n      </div>\n\n      <!-- Quick Bar: 1-Click Persona Switcher + Scenario Seeder -->\n      <div class=\"devops-quickbar\">\n        <div class=\"devops-quick-group\">\n          <span class=\"quick-title\">👤 1-Click Session Switcher:</span>\n          <div id=\"devops-user-switcher\" class=\"devops-user-pills\"></div>\n        </div>\n\n        <div class=\"devops-quick-group\">\n          <span class=\"quick-title\">🎬 Presentation Scenario State:</span>\n          <div class=\"devops-scenario-btns\">\n            <button class=\"devops-btn devops-btn-cyan\" onclick=\"loadScenario('full_demo')\">\n              ★ Full Demo (Match + Pending Claim + Flagged)\n            </button>\n            <button class=\"devops-btn\" onclick=\"loadScenario('matched_stage')\">\n              ⚡ Ahmed &amp; Khalid Matched (Before Claim)\n            </button>\n            <button class=\"devops-btn\" onclick=\"loadScenario('clean_stage')\">\n              🧹 Clean Slate (Live Report Demo)\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <!-- Console Navigation Tabs -->\n      <div class=\"devops-tabs\">\n        <button class=\"devops-tab active\" data-dtab=\"claims\" onclick=\"switchDevOpsTab('claims')\">\n          🛡️ Review Ownership Claims &amp; Handover (BPMN Fig. 1 &amp; 5)\n          <span id=\"dtab-claims-count\" class=\"dtab-badge\">0</span>\n        </button>\n        <button class=\"devops-tab\" data-dtab=\"moderation\" onclick=\"switchDevOpsTab('moderation')\">\n          🚨 Suspicious / Duplicate Reports (BPMN Fig. 4)\n          <span id=\"dtab-mod-count\" class=\"dtab-badge\">0</span>\n        </button>\n        <button class=\"devops-tab\" data-dtab=\"telemetry\" onclick=\"switchDevOpsTab('telemetry')\">\n          📊 SQLite DB &amp; NFR Telemetry Logs\n        </button>\n      </div>\n\n      <!-- Console Body -->\n      <div class=\"devops-body\">\n        <!-- DEVOPS TAB 1: CLAIMS & HANDOVER -->\n        <div id=\"dpanel-claims\" class=\"devops-panel\">\n          <div id=\"devops-claims-container\" class=\"devops-claims-grid\"></div>\n        </div>\n\n        <!-- DEVOPS TAB 2: SUSPICIOUS REPORT MODERATION (BPMN Fig. 4) -->\n        <div id=\"dpanel-moderation\" class=\"devops-panel hidden\">\n          <div class=\"devops-panel-intro\">\n            <strong>BPMN Figure 4 Workflow:</strong> Select a flagged/suspicious report and apply one of the three Review Decisions:\n            <em>(1) Valid &rarr; Dismiss Review Flag</em>, <em>(2) Modify &rarr; Update or Delete Report</em>, or <em>(3) Violates &rarr; Suspend User</em>. Each action sends an Admin Notice to the student.\n          </div>\n          <div id=\"devops-moderation-container\" class=\"devops-mod-grid\"></div>\n        </div>\n\n        <!-- DEVOPS TAB 3: SQLITE & NFR TELEMETRY -->\n        <div id=\"dpanel-telemetry\" class=\"devops-panel hidden\">\n          <div class=\"devops-telemetry-grid\">\n            <div class=\"telemetry-card\">\n              <h4>Non-Functional Requirements (NFR) Live Status</h4>\n              <ul class=\"nfr-status-list\" id=\"devops-nfr-list\"></ul>\n            </div>\n            <div class=\"telemetry-card\">\n              <h4>SQLite Accounts (`users` table in `reclaim.db`)</h4>\n              <div id=\"devops-users-table-wrap\"></div>\n            </div>\n          </div>\n\n          <div class=\"telemetry-card mt-16\">\n            <h4>Live SQLite &amp; Matching Engine Event Log (`system_logs`)</h4>\n            <div id=\"devops-logs-terminal\" class=\"devops-terminal\"></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Toast Notification Popup -->\n  <div id=\"toast-container\" class=\"toast-container\"></div>\n\n  <script src=\"/app.js\"></script>\n</body>\n</html>\n\n","/":"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"UTF-8\" />\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n  <title>Reclaim — Campus Lost &amp; Found System</title>\n  <link rel=\"stylesheet\" href=\"/styles.css\" />\n</head>\n<body>\n\n  <!-- ==================== 1. UNIFIED LOGIN SCREEN (NO REGISTER PAGE) ==================== -->\n  <section id=\"login-screen\" class=\"login-screen\">\n    <div class=\"login-container\">\n      <!-- Left Branding Panel -->\n      <div class=\"login-hero\">\n        <div class=\"brand-badge\">\n          <span class=\"brand-icon\">◈</span>\n          <span>UNIVERSITY VERIFIED PLATFORM</span>\n        </div>\n        <h1 class=\"hero-logo-title\">reclaim<span>.</span></h1>\n        <p class=\"hero-subtitle\">\n          The centralized, privacy-first Campus Lost &amp; Found platform powered by automated matching and administrator-verified ownership claims.\n        </p>\n\n        <div class=\"hero-features\">\n          <div class=\"hero-feature-item\">\n            <div class=\"feature-icon\">⚡</div>\n            <div>\n              <h4>&lt; 3s Automated Matching Engine</h4>\n              <p>Instantly cross-references lost and found reports across campus buildings, categories, colors, and brands.</p>\n            </div>\n          </div>\n          <div class=\"hero-feature-item\">\n            <div class=\"feature-icon\">🔒</div>\n            <div>\n              <h4>Privacy Blur &amp; Identity Protection</h4>\n              <p>Found item photos are blurred for public viewers to prevent false claims, and personal contact info is never exposed.</p>\n            </div>\n          </div>\n          <div class=\"hero-feature-item\">\n            <div class=\"feature-icon\">🛡️</div>\n            <div>\n              <h4>Admin Verification &amp; SQLite Persistence</h4>\n              <p>Side-by-side visual proof inspection, additional proof requests, and physical handover tracking.</p>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"hero-footer-pill\">\n          <span class=\"status-dot\"></span>\n          <span>SQLite Engine Active • Localhost Prototype</span>\n        </div>\n      </div>\n\n      <!-- Right Single Login Form Panel -->\n      <div class=\"login-card\">\n        <div class=\"login-card-header\">\n          <h2>Sign In to Reclaim</h2>\n          <p>\n            Enter any username and password. <strong>If the account doesn't exist yet, Reclaim automatically creates and remembers it in SQLite.</strong>\n          </p>\n        </div>\n\n        <form id=\"login-form\" class=\"login-form\">\n          <div class=\"form-group\">\n            <label for=\"login-username\">Campus Username</label>\n            <input\n              type=\"text\"\n              id=\"login-username\"\n              placeholder=\"e.g. ahmed, khalid, admin, or your name\"\n              required\n              autocomplete=\"username\"\n            />\n          </div>\n\n          <div class=\"form-group\">\n            <label for=\"login-password\">Password</label>\n            <input\n              type=\"password\"\n              id=\"login-password\"\n              placeholder=\"Enter password (saved automatically)\"\n              required\n              autocomplete=\"current-password\"\n            />\n          </div>\n\n          <div id=\"login-error\" class=\"alert-box alert-error hidden\"></div>\n\n          <button type=\"submit\" class=\"btn btn-primary btn-block btn-lg\">\n            Continue to Reclaim →\n          </button>\n        </form>\n\n        <div class=\"quick-demo-login\">\n          <span class=\"quick-demo-label\">Presentation 1-Click Fill:</span>\n          <div class=\"quick-demo-chips\">\n            <button type=\"button\" class=\"demo-chip\" onclick=\"quickFillLogin('ahmed', '1234')\">\n              🎓 <strong>ahmed</strong> (Lost Owner)\n            </button>\n            <button type=\"button\" class=\"demo-chip\" onclick=\"quickFillLogin('khalid', '1234')\">\n              🔍 <strong>khalid</strong> (Finder)\n            </button>\n            <button type=\"button\" class=\"demo-chip demo-chip-admin\" onclick=\"quickFillLogin('admin', 'admin')\">\n              🛡️ <strong>admin</strong> (Administrator)\n            </button>\n          </div>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <!-- ==================== 2. MAIN APPLICATION SHELL ==================== -->\n  <div id=\"app-shell\" class=\"app-shell hidden\">\n    <!-- Top Header Navigation -->\n    <header class=\"top-navbar\">\n      <div class=\"nav-left\">\n        <div class=\"app-logo\" onclick=\"switchView('home')\">\n          <span class=\"logo-mark\">◈</span>\n          <span class=\"logo-text\">reclaim<span class=\"logo-dot\">.</span></span>\n          <span class=\"campus-tag\">CAMPUS L&amp;F</span>\n        </div>\n\n        <nav class=\"main-nav\">\n          <button class=\"nav-btn active\" data-view=\"home\" onclick=\"switchView('home')\">\n            🏠 Home\n          </button>\n          <button class=\"nav-btn\" data-view=\"browse\" onclick=\"switchView('browse')\">\n            🔍 Search &amp; Browse\n          </button>\n          <button class=\"nav-btn\" data-view=\"report\" onclick=\"switchView('report')\">\n            ➕ Report Item\n          </button>\n          <button class=\"nav-btn\" data-view=\"claims\" onclick=\"switchView('claims')\">\n            📋 Matches &amp; Claims\n            <span id=\"nav-claims-badge\" class=\"nav-badge hidden\">0</span>\n          </button>\n          <button id=\"nav-admin-tab\" class=\"nav-btn nav-btn-admin hidden\" data-view=\"admin\" onclick=\"switchView('admin')\">\n            🛡️ Admin Workspace\n            <span id=\"nav-admin-badge\" class=\"nav-badge nav-badge-warn\">0</span>\n          </button>\n        </nav>\n      </div>\n\n      <div class=\"nav-right\">\n        <!-- Notification Bell -->\n        <button class=\"icon-btn\" onclick=\"toggleNotificationsDrawer()\" title=\"System Notifications\">\n          🔔\n          <span id=\"notif-unread-badge\" class=\"notif-badge hidden\">0</span>\n        </button>\n\n        <!-- Current User Pill -->\n        <div class=\"user-profile-pill\">\n          <div class=\"user-avatar\" id=\"header-user-avatar\">A</div>\n          <div class=\"user-meta\">\n            <span id=\"header-username\" class=\"user-name\">@ahmed</span>\n            <span id=\"header-user-role\" class=\"user-role-tag\">Student</span>\n          </div>\n        </div>\n\n        <button class=\"btn btn-outline btn-sm\" onclick=\"handleLogout()\">\n          Sign Out\n        </button>\n      </div>\n    </header>\n\n    <!-- Main Content Viewport -->\n    <main class=\"main-content\">\n\n      <!-- VIEW 1: HOME DASHBOARD -->\n      <section id=\"view-home\" class=\"view-section\">\n        <div class=\"hero-banner\">\n          <div class=\"hero-banner-text\">\n            <div class=\"hero-pill\">✨ Main Scenario &amp; Live Campus Feed</div>\n            <h1 id=\"welcome-headline\">Welcome back to Reclaim</h1>\n            <p>\n              Lost something after a lecture or found an unattended item on campus? Report it in seconds—our automated matching engine scans complementary reports in under 3 seconds while protecting student privacy.\n            </p>\n            <div class=\"hero-actions\">\n              <button class=\"btn btn-light-solid\" onclick=\"openReportForm('LOST')\">\n                📢 Report Lost Item\n              </button>\n              <button class=\"btn btn-glass\" onclick=\"openReportForm('FOUND')\">\n                📦 Report Found Item\n              </button>\n              <button class=\"btn btn-glass\" onclick=\"switchView('browse')\">\n                🔎 Search Campus Items\n              </button>\n            </div>\n          </div>\n\n          <div class=\"hero-stats-grid\">\n            <div class=\"stat-card\">\n              <span class=\"stat-value\" id=\"stat-total-reports\">0</span>\n              <span class=\"stat-label\">Active Campus Reports</span>\n            </div>\n            <div class=\"stat-card\">\n              <span class=\"stat-value\" id=\"stat-total-matches\">0</span>\n              <span class=\"stat-label\">Auto-Matches Suggested</span>\n            </div>\n            <div class=\"stat-card\">\n              <span class=\"stat-value\" id=\"stat-match-speed\">1.1 ms</span>\n              <span class=\"stat-label\">Match Engine Speed (&lt;3s NFR)</span>\n            </div>\n            <div class=\"stat-card\">\n              <span class=\"stat-value\" id=\"stat-resolved-cases\">0</span>\n              <span class=\"stat-label\">Items Verified &amp; Returned</span>\n            </div>\n          </div>\n        </div>\n\n        <!-- Automated Suggested Matches Banner -->\n        <div class=\"section-block\">\n          <div class=\"section-header\">\n            <div>\n              <h2>⚡ Automated Match Suggestions</h2>\n              <p>Real-time matches discovered by comparing Category, Building Location, Color, Brand, and Keywords.</p>\n            </div>\n            <button class=\"btn btn-outline btn-sm\" onclick=\"switchView('claims')\">\n              View All Matches &amp; Claims →\n            </button>\n          </div>\n          <div id=\"home-matches-container\" class=\"matches-grid\"></div>\n        </div>\n\n        <!-- Recent Campus Reports -->\n        <div class=\"section-block\">\n          <div class=\"section-header\">\n            <div>\n              <h2>📍 Recent Campus Reports</h2>\n              <p>Note: Found item photos are automatically blurred for students to prevent fraudulent claims.</p>\n            </div>\n            <button class=\"btn btn-outline btn-sm\" onclick=\"switchView('browse')\">\n              Open Search &amp; Filters →\n            </button>\n          </div>\n          <div id=\"home-reports-container\" class=\"reports-grid\"></div>\n        </div>\n      </section>\n\n      <!-- VIEW 2: SEARCH & BROWSE ITEMS (Use Case 3 / BPMN Fig. 3) -->\n      <section id=\"view-browse\" class=\"view-section hidden\">\n        <div class=\"page-title-bar\">\n          <div>\n            <h2>🔍 Search &amp; Filter Campus Listings</h2>\n            <p>Search reported Lost &amp; Found items across campus buildings. Found item photos use Privacy Blur protection.</p>\n          </div>\n          <div class=\"page-title-actions\">\n            <button class=\"btn btn-primary\" onclick=\"openReportForm('LOST')\">+ Report Lost</button>\n            <button class=\"btn btn-secondary\" onclick=\"openReportForm('FOUND')\">+ Report Found</button>\n          </div>\n        </div>\n\n        <!-- Filter Bar -->\n        <div class=\"filter-bar\">\n          <div class=\"filter-group filter-search\">\n            <label>Keyword Search</label>\n            <input type=\"text\" id=\"filter-q\" placeholder=\"Search charger, calculator, bottle, Dell...\" oninput=\"applySearchFilters()\" />\n          </div>\n          <div class=\"filter-group\">\n            <label>Report Type</label>\n            <select id=\"filter-type\" onchange=\"applySearchFilters()\">\n              <option value=\"ALL\">All Types (Lost &amp; Found)</option>\n              <option value=\"FOUND\">Found Items Only</option>\n              <option value=\"LOST\">Lost Items Only</option>\n            </select>\n          </div>\n          <div class=\"filter-group\">\n            <label>Category</label>\n            <select id=\"filter-category\" onchange=\"applySearchFilters()\">\n              <option value=\"ALL\">All Categories</option>\n              <option value=\"Electronics\">Electronics</option>\n              <option value=\"ID & Cards\">ID &amp; Cards</option>\n              <option value=\"Bottles & Accessories\">Bottles &amp; Accessories</option>\n              <option value=\"Books & Notes\">Books &amp; Notes</option>\n              <option value=\"Keys & Wallets\">Keys &amp; Wallets</option>\n            </select>\n          </div>\n          <div class=\"filter-group\">\n            <label>Campus Building</label>\n            <select id=\"filter-location\" onchange=\"applySearchFilters()\">\n              <option value=\"ALL\">All Campus Buildings</option>\n              <option value=\"Engineering Building\">Engineering Building</option>\n              <option value=\"Main Library\">Main Library</option>\n              <option value=\"Student Center\">Student Center</option>\n              <option value=\"Science Complex\">Science Complex</option>\n              <option value=\"Cafeteria\">Cafeteria</option>\n              <option value=\"Sports Hall\">Sports Hall</option>\n            </select>\n          </div>\n          <div class=\"filter-group\">\n            <label>Color</label>\n            <select id=\"filter-color\" onchange=\"applySearchFilters()\">\n              <option value=\"ALL\">All Colors</option>\n              <option value=\"Black\">Black</option>\n              <option value=\"Blue\">Blue</option>\n              <option value=\"White\">White</option>\n              <option value=\"Silver\">Silver</option>\n              <option value=\"Purple\">Purple</option>\n              <option value=\"Red\">Red</option>\n            </select>\n          </div>\n          <div class=\"filter-group filter-reset\">\n            <label>&nbsp;</label>\n            <button class=\"btn btn-outline\" onclick=\"resetSearchFilters()\">Reset</button>\n          </div>\n        </div>\n\n        <div id=\"browse-reports-container\" class=\"reports-grid\"></div>\n      </section>\n\n      <!-- VIEW 3: REPORT LOST OR FOUND ITEM (Use Case 2 & 3 / BPMN Fig. 2 & 3) -->\n      <section id=\"view-report\" class=\"view-section hidden\">\n        <div class=\"form-card-wrapper\">\n          <div class=\"report-type-switcher\">\n            <button type=\"button\" id=\"tab-btn-lost\" class=\"type-switch-btn active-lost\" onclick=\"setReportFormType('LOST')\">\n              📢 Report a Lost Item\n              <span>I lost something on campus</span>\n            </button>\n            <button type=\"button\" id=\"tab-btn-found\" class=\"type-switch-btn\" onclick=\"setReportFormType('FOUND')\">\n              📦 Report a Found Item\n              <span>I found an item &amp; will hand it to Admin</span>\n            </button>\n          </div>\n\n          <form id=\"create-report-form\" class=\"report-form\">\n            <input type=\"hidden\" id=\"report-type-input\" value=\"LOST\" />\n\n            <div class=\"form-banner-info\" id=\"report-form-banner\">\n              <strong>Lost Item Report:</strong> Provide accurate details and an old photo if available. Our automated matching engine will scan existing Found reports in &lt; 3 seconds.\n            </div>\n\n            <!-- 1-Click Scenario Auto-Fill Bar for Live Presentation -->\n            <div class=\"preset-autofill-bar\">\n              <span>⚡ Quick Presentation Auto-Fill:</span>\n              <button type=\"button\" class=\"btn-chip\" onclick=\"autofillAhmedLostCharger()\">\n                Fill Ahmed's Lost Black Charger\n              </button>\n              <button type=\"button\" class=\"btn-chip\" onclick=\"autofillKhalidFoundCharger()\">\n                Fill Khalid's Found Black Charger\n              </button>\n            </div>\n\n            <div class=\"form-grid-2\">\n              <div class=\"form-group\">\n                <label>Item Title *</label>\n                <input type=\"text\" id=\"rep-title\" placeholder=\"e.g. Black Laptop Charger (65W USB-C)\" required />\n              </div>\n\n              <div class=\"form-group\">\n                <label>Category *</label>\n                <select id=\"rep-category\" required>\n                  <option value=\"Electronics\">Electronics</option>\n                  <option value=\"ID & Cards\">ID &amp; Cards</option>\n                  <option value=\"Bottles & Accessories\">Bottles &amp; Accessories</option>\n                  <option value=\"Books & Notes\">Books &amp; Notes</option>\n                  <option value=\"Keys & Wallets\">Keys &amp; Wallets</option>\n                </select>\n              </div>\n\n              <div class=\"form-group\">\n                <label>Primary Color *</label>\n                <select id=\"rep-color\" required>\n                  <option value=\"Black\">Black</option>\n                  <option value=\"Blue\">Blue</option>\n                  <option value=\"White\">White</option>\n                  <option value=\"Silver\">Silver</option>\n                  <option value=\"Purple\">Purple</option>\n                  <option value=\"Red\">Red</option>\n                </select>\n              </div>\n\n              <div class=\"form-group\">\n                <label>Brand / Make</label>\n                <input type=\"text\" id=\"rep-brand\" placeholder=\"e.g. Dell, Apple, Casio, HydroFlask\" />\n              </div>\n\n              <div class=\"form-group\">\n                <label>Campus Building / Location *</label>\n                <select id=\"rep-location\" required>\n                  <option value=\"Engineering Building\">Engineering Building</option>\n                  <option value=\"Main Library\">Main Library</option>\n                  <option value=\"Student Center\">Student Center</option>\n                  <option value=\"Science Complex\">Science Complex</option>\n                  <option value=\"Cafeteria\">Cafeteria</option>\n                  <option value=\"Sports Hall\">Sports Hall</option>\n                </select>\n              </div>\n\n              <div class=\"form-group\">\n                <label>Date &amp; Approximate Time *</label>\n                <input type=\"text\" id=\"rep-date\" value=\"Today, 10:30 AM\" required />\n              </div>\n            </div>\n\n            <div class=\"form-group\">\n              <label>General Description *</label>\n              <textarea id=\"rep-description\" rows=\"3\" placeholder=\"Describe where and how the item was lost or found...\" required></textarea>\n            </div>\n\n            <div class=\"form-group\">\n              <label>Unique Identifiers / Distinguishing Marks (Serial #, Stickers, Scratches)</label>\n              <input\n                type=\"text\"\n                id=\"rep-marks\"\n                placeholder=\"e.g. Blue velcro cable strap, Serial CN-065W-AH92 (Hidden from public on Found items)\"\n              />\n            </div>\n\n            <!-- BPMN Fig. 2 Physical Item Handover Checkbox (Only for FOUND items) -->\n            <div id=\"found-handover-box\" class=\"handover-checkbox-box hidden\">\n              <label class=\"checkbox-label\">\n                <input type=\"checkbox\" id=\"rep-handed\" checked />\n                <span>\n                  <strong>BPMN Fig. 2 Requirement:</strong> I confirm that I am handing over the physical item to the Campus Lost &amp; Found Administrator Office.\n                </span>\n              </label>\n            </div>\n\n            <!-- NFR Image Upload & Automatic <3MB Compression -->\n            <div class=\"form-group\">\n              <label>Item Photo (NFR: Auto-Compressed &le; 3.0 MB; Blurred automatically if Found Item)</label>\n              <div class=\"photo-upload-zone\">\n                <div class=\"photo-upload-controls\">\n                  <input type=\"file\" id=\"rep-file-input\" accept=\"image/*\" onchange=\"handleImageUpload(event, 'report')\" />\n                  <div class=\"preset-photo-selector\">\n                    <span>Or choose sample photo:</span>\n                    <button type=\"button\" class=\"btn-chip\" onclick=\"selectPresetPhoto('charger_lost', 'report')\">🔌 Charger (Owner)</button>\n                    <button type=\"button\" class=\"btn-chip\" onclick=\"selectPresetPhoto('charger_found', 'report')\">🔌 Charger (Found)</button>\n                    <button type=\"button\" class=\"btn-chip\" onclick=\"selectPresetPhoto('hydroflask', 'report')\">🧴 Water Bottle</button>\n                    <button type=\"button\" class=\"btn-chip\" onclick=\"selectPresetPhoto('calculator', 'report')\">🧮 Calculator</button>\n                    <button type=\"button\" class=\"btn-chip\" onclick=\"selectPresetPhoto('airpods', 'report')\">🎧 AirPods</button>\n                  </div>\n                  <div id=\"compression-telemetry\" class=\"compression-badge\">\n                    ✅ NFR Image Compression Ready: <strong>192.4 KB</strong> / 3,072 KB max limit\n                  </div>\n                </div>\n                <div class=\"photo-preview-box\">\n                  <img id=\"rep-photo-preview\" src=\"\" alt=\"Preview\" />\n                </div>\n              </div>\n            </div>\n\n            <div class=\"form-submit-row\">\n              <button type=\"submit\" class=\"btn btn-primary btn-lg\">\n                Submit Report &amp; Run Auto-Matcher →\n              </button>\n            </div>\n          </form>\n        </div>\n      </section>\n\n      <!-- VIEW 4: MATCHES & OWNERSHIP CLAIMS (Use Case 1 / BPMN Fig. 1 & Fig. 5) -->\n      <section id=\"view-claims\" class=\"view-section hidden\">\n        <div class=\"section-block\">\n          <div class=\"section-header\">\n            <div>\n              <h2>⚡ Suggested Matches for Your Reports</h2>\n              <p>Click \"Submit Ownership Claim\" on any matching Found item to provide proof of ownership to the Administrator.</p>\n            </div>\n          </div>\n          <div id=\"claims-view-matches\" class=\"matches-grid\"></div>\n        </div>\n\n        <div class=\"section-block\">\n          <div class=\"section-header\">\n            <div>\n              <h2>📋 Ownership Claims &amp; Verification Status</h2>\n              <p>Track your claims from <strong>Pending</strong> &rarr; <strong>More Proof Requested / Approved</strong> &rarr; <strong>Confirm Item Receipt</strong> &rarr; <strong>Returned &amp; Resolved</strong>.</p>\n            </div>\n          </div>\n          <div id=\"student-claims-container\" class=\"claims-list\"></div>\n        </div>\n      </section>\n\n      <!-- VIEW 5: DEDICATED ADMIN WORKSPACE (When logged in as Admin) -->\n      <section id=\"view-admin\" class=\"view-section hidden\">\n        <div class=\"admin-workspace-banner\">\n          <div>\n            <span class=\"admin-pill\">🛡️ ROLE-BASED ACCESS CONTROL: ADMINISTRATOR</span>\n            <h2>Lost &amp; Found Administrator Command Center</h2>\n            <p>Review pending ownership claims side-by-side with unblurred photos, request more proof, log physical handovers (BPMN Fig. 5), and moderate flagged reports (BPMN Fig. 4).</p>\n          </div>\n          <button class=\"btn btn-devops-trigger\" onclick=\"toggleDevOpsModal(true)\">\n            ⚡ Open Full Dark-Blue DevOps Overlay\n          </button>\n        </div>\n\n        <div class=\"section-block\">\n          <h3>1. Pending &amp; Active Ownership Claims (BPMN Fig. 1 &amp; Fig. 5)</h3>\n          <div id=\"admin-page-claims-list\" class=\"claims-list\"></div>\n        </div>\n\n        <div class=\"section-block\">\n          <h3>2. Flagged Suspicious / Duplicate Reports (BPMN Fig. 4)</h3>\n          <div id=\"admin-page-suspicious-list\" class=\"reports-grid\"></div>\n        </div>\n      </section>\n\n    </main>\n  </div>\n\n  <!-- ==================== 3. SUBMIT OWNERSHIP CLAIM MODAL ==================== -->\n  <div id=\"claim-modal\" class=\"modal-backdrop hidden\">\n    <div class=\"modal-card\">\n      <div class=\"modal-header\">\n        <div>\n          <h3>🛡️ Submit Ownership Claim (Use Case 1)</h3>\n          <p id=\"claim-modal-subtitle\">Provide proof of ownership so the Administrator can verify and release your item.</p>\n        </div>\n        <button class=\"close-btn\" onclick=\"closeClaimModal()\">✕</button>\n      </div>\n\n      <form id=\"submit-claim-form\" class=\"modal-body\">\n        <input type=\"hidden\" id=\"claim-found-report-id\" />\n        <input type=\"hidden\" id=\"claim-lost-report-id\" />\n\n        <div class=\"preset-autofill-bar\">\n          <span>⚡ Presentation Helper:</span>\n          <button type=\"button\" class=\"btn-chip\" onclick=\"autofillAhmedClaimProof()\">\n            Auto-Fill Ahmed's Charger Proof (Serial # + Blue Strap Photo)\n          </button>\n        </div>\n\n        <div class=\"form-group\">\n          <label>Proof of Ownership Description (Serial Number, Receipts, Distinguishing Marks) *</label>\n          <textarea\n            id=\"claim-proof-text\"\n            rows=\"4\"\n            placeholder=\"Describe unique identifiers that prove this item belongs to you (e.g. Serial number CN-065W-AH92, blue velcro strap, receipt details)...\"\n            required\n          ></textarea>\n        </div>\n\n        <div class=\"form-group\">\n          <label>Upload Visual Proof Photo (Receipt, Old Photo, or Serial Tag)</label>\n          <div class=\"photo-upload-zone compact\">\n            <div class=\"photo-upload-controls\">\n              <input type=\"file\" accept=\"image/*\" onchange=\"handleImageUpload(event, 'claim')\" />\n              <div class=\"preset-photo-selector\">\n                <button type=\"button\" class=\"btn-chip\" onclick=\"selectPresetPhoto('charger_proof', 'claim')\">\n                  📷 Use Ahmed's Serial # Proof Photo\n                </button>\n                <button type=\"button\" class=\"btn-chip\" onclick=\"selectPresetPhoto('charger_lost', 'claim')\">\n                  📷 Use Original Charger Photo\n                </button>\n              </div>\n            </div>\n            <div class=\"photo-preview-box small\">\n              <img id=\"claim-photo-preview\" src=\"\" alt=\"Proof Preview\" />\n            </div>\n          </div>\n        </div>\n\n        <div class=\"modal-footer\">\n          <button type=\"button\" class=\"btn btn-outline\" onclick=\"closeClaimModal()\">Cancel</button>\n          <button type=\"submit\" class=\"btn btn-primary\">Submit Claim (Status &rarr; Pending)</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- ==================== 4. SUBMIT ADDITIONAL PROOF MODAL (BPMN Fig. 1 Loop) ==================== -->\n  <div id=\"more-proof-modal\" class=\"modal-backdrop hidden\">\n    <div class=\"modal-card\">\n      <div class=\"modal-header\">\n        <div>\n          <h3>🔎 Provide Additional Proof (BPMN Fig. 1)</h3>\n          <p>The Administrator requested additional proof before approving your ownership claim.</p>\n        </div>\n        <button class=\"close-btn\" onclick=\"closeMoreProofModal()\">✕</button>\n      </div>\n      <form id=\"more-proof-form\" class=\"modal-body\">\n        <input type=\"hidden\" id=\"more-proof-claim-id\" />\n        <div id=\"more-proof-admin-prompt\" class=\"alert-box alert-warn\"></div>\n\n        <div class=\"form-group\">\n          <label>Additional Proof Details / Serial Confirmation *</label>\n          <textarea\n            id=\"more-proof-text\"\n            rows=\"3\"\n            placeholder=\"Enter the additional details requested by the Administrator...\"\n            required\n          >Here is the exact purchase invoice #INV-99281 and close-up photo of the serial tag CN-065W-AH92 on the adapter brick.</textarea>\n        </div>\n\n        <div class=\"modal-footer\">\n          <button type=\"button\" class=\"btn btn-outline\" onclick=\"closeMoreProofModal()\">Cancel</button>\n          <button type=\"submit\" class=\"btn btn-primary\">Resubmit Proof to Administrator →</button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- ==================== 5. NOTIFICATIONS SLIDE-OVER DRAWER ==================== -->\n  <div id=\"notifications-drawer\" class=\"notif-drawer hidden\">\n    <div class=\"notif-drawer-header\">\n      <div>\n        <h3>🔔 System Notifications</h3>\n        <span class=\"notif-sub\">Privacy-protected real-time alerts</span>\n      </div>\n      <div class=\"notif-header-actions\">\n        <button class=\"btn-link\" onclick=\"markAllNotificationsRead()\">Mark all read</button>\n        <button class=\"close-btn\" onclick=\"toggleNotificationsDrawer(false)\">✕</button>\n      </div>\n    </div>\n    <div id=\"notifications-list\" class=\"notif-drawer-body\"></div>\n  </div>\n\n  <!-- ==================== 6. FLOATING BOTTOM-RIGHT DEVOPS / ADMIN BUTTON ==================== -->\n  <button id=\"devops-floating-btn\" class=\"devops-fab\" onclick=\"toggleDevOpsModal()\">\n    <span class=\"devops-fab-pulse\"></span>\n    <span class=\"devops-fab-icon\">⚡</span>\n    <div class=\"devops-fab-text\">\n      <strong>DevOps / Admin</strong>\n      <span>Control Panel</span>\n    </div>\n    <span id=\"devops-fab-badge\" class=\"devops-fab-badge\">1</span>\n  </button>\n\n  <!-- ==================== 7. COOL DARK-BLUE TINTED DEVOPS & ADMIN CONSOLE ==================== -->\n  <div id=\"devops-overlay\" class=\"devops-overlay hidden\">\n    <div class=\"devops-console\">\n      <!-- Console Top Header -->\n      <div class=\"devops-header\">\n        <div class=\"devops-title-group\">\n          <span class=\"devops-chip\">DARK-BLUE DEVOPS &amp; ADMIN ENGINE</span>\n          <h2>⚡ Reclaim DevOps &amp; Administrator Console</h2>\n          <p>Inspect SQLite state, switch active user personas in 1 click, verify claims (request more proof / approve / mark returned), and moderate reports.</p>\n        </div>\n        <button class=\"devops-close-btn\" onclick=\"toggleDevOpsModal(false)\">✕ Close Console</button>\n      </div>\n\n      <!-- Quick Bar: 1-Click Persona Switcher + Scenario Seeder -->\n      <div class=\"devops-quickbar\">\n        <div class=\"devops-quick-group\">\n          <span class=\"quick-title\">👤 1-Click Session Switcher:</span>\n          <div id=\"devops-user-switcher\" class=\"devops-user-pills\"></div>\n        </div>\n\n        <div class=\"devops-quick-group\">\n          <span class=\"quick-title\">🎬 Presentation Scenario State:</span>\n          <div class=\"devops-scenario-btns\">\n            <button class=\"devops-btn devops-btn-cyan\" onclick=\"loadScenario('full_demo')\">\n              ★ Full Demo (Match + Pending Claim + Flagged)\n            </button>\n            <button class=\"devops-btn\" onclick=\"loadScenario('matched_stage')\">\n              ⚡ Ahmed &amp; Khalid Matched (Before Claim)\n            </button>\n            <button class=\"devops-btn\" onclick=\"loadScenario('clean_stage')\">\n              🧹 Clean Slate (Live Report Demo)\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <!-- Console Navigation Tabs -->\n      <div class=\"devops-tabs\">\n        <button class=\"devops-tab active\" data-dtab=\"claims\" onclick=\"switchDevOpsTab('claims')\">\n          🛡️ Review Ownership Claims &amp; Handover (BPMN Fig. 1 &amp; 5)\n          <span id=\"dtab-claims-count\" class=\"dtab-badge\">0</span>\n        </button>\n        <button class=\"devops-tab\" data-dtab=\"moderation\" onclick=\"switchDevOpsTab('moderation')\">\n          🚨 Suspicious / Duplicate Reports (BPMN Fig. 4)\n          <span id=\"dtab-mod-count\" class=\"dtab-badge\">0</span>\n        </button>\n        <button class=\"devops-tab\" data-dtab=\"telemetry\" onclick=\"switchDevOpsTab('telemetry')\">\n          📊 SQLite DB &amp; NFR Telemetry Logs\n        </button>\n      </div>\n\n      <!-- Console Body -->\n      <div class=\"devops-body\">\n        <!-- DEVOPS TAB 1: CLAIMS & HANDOVER -->\n        <div id=\"dpanel-claims\" class=\"devops-panel\">\n          <div id=\"devops-claims-container\" class=\"devops-claims-grid\"></div>\n        </div>\n\n        <!-- DEVOPS TAB 2: SUSPICIOUS REPORT MODERATION (BPMN Fig. 4) -->\n        <div id=\"dpanel-moderation\" class=\"devops-panel hidden\">\n          <div class=\"devops-panel-intro\">\n            <strong>BPMN Figure 4 Workflow:</strong> Select a flagged/suspicious report and apply one of the three Review Decisions:\n            <em>(1) Valid &rarr; Dismiss Review Flag</em>, <em>(2) Modify &rarr; Update or Delete Report</em>, or <em>(3) Violates &rarr; Suspend User</em>. Each action sends an Admin Notice to the student.\n          </div>\n          <div id=\"devops-moderation-container\" class=\"devops-mod-grid\"></div>\n        </div>\n\n        <!-- DEVOPS TAB 3: SQLITE & NFR TELEMETRY -->\n        <div id=\"dpanel-telemetry\" class=\"devops-panel hidden\">\n          <div class=\"devops-telemetry-grid\">\n            <div class=\"telemetry-card\">\n              <h4>Non-Functional Requirements (NFR) Live Status</h4>\n              <ul class=\"nfr-status-list\" id=\"devops-nfr-list\"></ul>\n            </div>\n            <div class=\"telemetry-card\">\n              <h4>SQLite Accounts (`users` table in `reclaim.db`)</h4>\n              <div id=\"devops-users-table-wrap\"></div>\n            </div>\n          </div>\n\n          <div class=\"telemetry-card mt-16\">\n            <h4>Live SQLite &amp; Matching Engine Event Log (`system_logs`)</h4>\n            <div id=\"devops-logs-terminal\" class=\"devops-terminal\"></div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Toast Notification Popup -->\n  <div id=\"toast-container\" class=\"toast-container\"></div>\n\n  <script src=\"/app.js\"></script>\n</body>\n</html>\n\n","/styles.css":":root {\n  --bg-page: #f1f5f9;\n  --bg-card: #ffffff;\n  --text-main: #0f172a;\n  --text-muted: #475569;\n  --text-light: #64748b;\n  --primary: #2563eb;\n  --primary-dark: #1d4ed8;\n  --primary-soft: #dbeafe;\n  --indigo: #4f46e5;\n  --emerald: #10b981;\n  --emerald-soft: #d1fae5;\n  --amber: #f59e0b;\n  --amber-soft: #fef3c7;\n  --rose: #ef4444;\n  --rose-soft: #fee2e2;\n  --border: #e2e8f0;\n  --shadow-sm: 0 2px 8px rgba(15, 23, 42, 0.05);\n  --shadow-md: 0 10px 25px -5px rgba(15, 23, 42, 0.08);\n  --shadow-lg: 0 20px 40px -12px rgba(15, 23, 42, 0.16);\n  --radius: 14px;\n}\n\n* {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n  background-color: var(--bg-page);\n  color: var(--text-main);\n  line-height: 1.5;\n  min-height: 100vh;\n}\n\n.hidden {\n  display: none !important;\n}\n\n/* ==================== 1. UNIFIED LOGIN SCREEN ==================== */\n.login-screen {\n  min-height: 100vh;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 28px;\n  background: radial-gradient(circle at 15% 20%, #1e3a8a 0%, #0f172a 52%, #050b18 100%);\n}\n\n.login-container {\n  width: 100%;\n  max-width: 1080px;\n  display: grid;\n  grid-template-columns: 1.15fr 0.95fr;\n  background: rgba(15, 23, 42, 0.72);\n  border: 1px solid rgba(96, 165, 250, 0.25);\n  border-radius: 24px;\n  overflow: hidden;\n  box-shadow: 0 25px 60px rgba(0, 0, 0, 0.55);\n  backdrop-filter: blur(16px);\n}\n\n.login-hero {\n  padding: 48px 44px;\n  color: #f8fafc;\n  background: linear-gradient(155deg, rgba(30, 58, 138, 0.65) 0%, rgba(15, 23, 42, 0.9) 100%);\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n}\n\n.brand-badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n  background: rgba(56, 189, 248, 0.15);\n  border: 1px solid rgba(56, 189, 248, 0.4);\n  color: #38bdf8;\n  padding: 6px 14px;\n  border-radius: 999px;\n  font-size: 12px;\n  font-weight: 700;\n  letter-spacing: 0.06em;\n  width: fit-content;\n}\n\n.hero-logo-title {\n  font-size: 54px;\n  font-weight: 800;\n  letter-spacing: -0.03em;\n  margin-top: 16px;\n  color: #ffffff;\n}\n\n.hero-logo-title span {\n  color: #38bdf8;\n}\n\n.hero-subtitle {\n  color: #cbd5e1;\n  font-size: 15.5px;\n  margin-top: 10px;\n  max-width: 480px;\n}\n\n.hero-features {\n  margin-top: 32px;\n  display: flex;\n  flex-direction: column;\n  gap: 18px;\n}\n\n.hero-feature-item {\n  display: flex;\n  align-items: flex-start;\n  gap: 14px;\n  background: rgba(255, 255, 255, 0.04);\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  padding: 14px 16px;\n  border-radius: 14px;\n}\n\n.feature-icon {\n  font-size: 22px;\n  background: rgba(59, 130, 246, 0.2);\n  width: 42px;\n  height: 42px;\n  border-radius: 10px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  flex-shrink: 0;\n}\n\n.hero-feature-item h4 {\n  font-size: 14.5px;\n  font-weight: 700;\n  color: #f1f5f9;\n}\n\n.hero-feature-item p {\n  font-size: 13px;\n  color: #94a3b8;\n  margin-top: 2px;\n}\n\n.hero-footer-pill {\n  margin-top: 32px;\n  display: inline-flex;\n  align-items: center;\n  gap: 10px;\n  font-size: 12.5px;\n  color: #94a3b8;\n}\n\n.status-dot {\n  width: 9px;\n  height: 9px;\n  background: #10b981;\n  border-radius: 50%;\n  box-shadow: 0 0 10px #10b981;\n}\n\n.login-card {\n  background: #ffffff;\n  padding: 48px 42px;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n}\n\n.login-card-header h2 {\n  font-size: 26px;\n  font-weight: 800;\n  color: #0f172a;\n}\n\n.login-card-header p {\n  font-size: 13.5px;\n  color: #475569;\n  margin-top: 8px;\n}\n\n.login-form {\n  margin-top: 26px;\n  display: flex;\n  flex-direction: column;\n  gap: 18px;\n}\n\n.form-group {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n}\n\n.form-group label {\n  font-size: 13px;\n  font-weight: 600;\n  color: #334155;\n}\n\n.form-group input,\n.form-group select,\n.form-group textarea {\n  padding: 11px 14px;\n  border: 1.5px solid #cbd5e1;\n  border-radius: 10px;\n  font-size: 14px;\n  font-family: inherit;\n  color: #0f172a;\n  background: #f8fafc;\n  transition: all 0.18s ease;\n}\n\n.form-group input:focus,\n.form-group select:focus,\n.form-group textarea:focus {\n  outline: none;\n  border-color: var(--primary);\n  background: #ffffff;\n  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.14);\n}\n\n.quick-demo-login {\n  margin-top: 28px;\n  padding-top: 20px;\n  border-top: 1px dashed #e2e8f0;\n}\n\n.quick-demo-label {\n  display: block;\n  font-size: 12px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  color: #64748b;\n  margin-bottom: 10px;\n}\n\n.quick-demo-chips {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n\n.demo-chip {\n  padding: 8px 12px;\n  border-radius: 9px;\n  border: 1px solid #cbd5e1;\n  background: #f8fafc;\n  font-size: 12.5px;\n  color: #1e293b;\n  cursor: pointer;\n  transition: all 0.15s;\n}\n\n.demo-chip:hover {\n  border-color: var(--primary);\n  background: #eff6ff;\n  color: var(--primary-dark);\n}\n\n.demo-chip-admin {\n  border-color: #93c5fd;\n  background: #eff6ff;\n}\n\n/* ==================== 2. TOP NAVIGATION BAR ==================== */\n.top-navbar {\n  position: sticky;\n  top: 0;\n  z-index: 100;\n  background: rgba(255, 255, 255, 0.92);\n  backdrop-filter: blur(12px);\n  border-bottom: 1px solid var(--border);\n  padding: 0 28px;\n  height: 70px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.nav-left {\n  display: flex;\n  align-items: center;\n  gap: 32px;\n}\n\n.app-logo {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  cursor: pointer;\n}\n\n.logo-mark {\n  width: 34px;\n  height: 34px;\n  border-radius: 10px;\n  background: linear-gradient(135deg, #1e40af, #3b82f6);\n  color: #ffffff;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-weight: 800;\n  font-size: 18px;\n}\n\n.logo-text {\n  font-size: 22px;\n  font-weight: 800;\n  letter-spacing: -0.03em;\n  color: #0f172a;\n}\n\n.logo-dot {\n  color: #2563eb;\n}\n\n.campus-tag {\n  font-size: 10px;\n  font-weight: 700;\n  padding: 3px 7px;\n  border-radius: 6px;\n  background: #dbeafe;\n  color: #1e40af;\n  margin-left: 4px;\n}\n\n.main-nav {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.nav-btn {\n  padding: 9px 15px;\n  border-radius: 10px;\n  border: none;\n  background: transparent;\n  color: #475569;\n  font-size: 13.5px;\n  font-weight: 600;\n  cursor: pointer;\n  display: inline-flex;\n  align-items: center;\n  gap: 7px;\n  transition: all 0.16s ease;\n}\n\n.nav-btn:hover {\n  background: #f1f5f9;\n  color: #0f172a;\n}\n\n.nav-btn.active {\n  background: #eff6ff;\n  color: #1d4ed8;\n  font-weight: 700;\n}\n\n.nav-btn-admin {\n  border: 1px solid #bfdbfe;\n  background: #f0f9ff;\n  color: #0369a1;\n}\n\n.nav-badge {\n  background: #2563eb;\n  color: #ffffff;\n  font-size: 11px;\n  font-weight: 700;\n  padding: 1px 7px;\n  border-radius: 99px;\n}\n\n.nav-badge-warn {\n  background: #f59e0b;\n}\n\n.nav-right {\n  display: flex;\n  align-items: center;\n  gap: 14px;\n}\n\n.icon-btn {\n  position: relative;\n  width: 40px;\n  height: 40px;\n  border-radius: 10px;\n  border: 1px solid var(--border);\n  background: #ffffff;\n  font-size: 18px;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.icon-btn:hover {\n  background: #f8fafc;\n}\n\n.notif-badge {\n  position: absolute;\n  top: -5px;\n  right: -5px;\n  background: #ef4444;\n  color: #fff;\n  font-size: 11px;\n  font-weight: 800;\n  padding: 1px 6px;\n  border-radius: 999px;\n  border: 2px solid #fff;\n}\n\n.user-profile-pill {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  padding: 5px 12px 5px 6px;\n  background: #f8fafc;\n  border: 1px solid var(--border);\n  border-radius: 999px;\n}\n\n.user-avatar {\n  width: 30px;\n  height: 30px;\n  border-radius: 50%;\n  background: linear-gradient(135deg, #2563eb, #4f46e5);\n  color: #fff;\n  font-weight: 700;\n  font-size: 13px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n}\n\n.user-meta {\n  display: flex;\n  flex-direction: column;\n  line-height: 1.15;\n}\n\n.user-name {\n  font-size: 13px;\n  font-weight: 700;\n  color: #0f172a;\n}\n\n.user-role-tag {\n  font-size: 10.5px;\n  font-weight: 600;\n  color: #2563eb;\n  text-transform: uppercase;\n}\n\n/* ==================== 3. MAIN CONTENT & HERO ==================== */\n.main-content {\n  max-width: 1280px;\n  margin: 0 auto;\n  padding: 28px 24px 110px;\n}\n\n.hero-banner {\n  background: linear-gradient(130deg, #0f172a 0%, #1e3a8a 58%, #1d4ed8 100%);\n  border-radius: 22px;\n  padding: 36px 38px;\n  color: #ffffff;\n  display: grid;\n  grid-template-columns: 1.25fr 1fr;\n  gap: 32px;\n  align-items: center;\n  box-shadow: var(--shadow-lg);\n}\n\n.hero-pill {\n  display: inline-block;\n  background: rgba(56, 189, 248, 0.2);\n  border: 1px solid rgba(56, 189, 248, 0.45);\n  color: #7dd3fc;\n  font-size: 12px;\n  font-weight: 700;\n  padding: 4px 12px;\n  border-radius: 999px;\n  margin-bottom: 12px;\n}\n\n.hero-banner-text h1 {\n  font-size: 32px;\n  font-weight: 800;\n  letter-spacing: -0.02em;\n}\n\n.hero-banner-text p {\n  color: #cbd5e1;\n  font-size: 14.5px;\n  margin-top: 8px;\n  max-width: 560px;\n}\n\n.hero-actions {\n  margin-top: 22px;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n\n.hero-stats-grid {\n  display: grid;\n  grid-template-columns: repeat(2, 1fr);\n  gap: 14px;\n}\n\n.stat-card {\n  background: rgba(255, 255, 255, 0.09);\n  border: 1px solid rgba(255, 255, 255, 0.16);\n  backdrop-filter: blur(10px);\n  padding: 18px 20px;\n  border-radius: 16px;\n  display: flex;\n  flex-direction: column;\n}\n\n.stat-value {\n  font-size: 28px;\n  font-weight: 800;\n  color: #38bdf8;\n}\n\n.stat-label {\n  font-size: 12px;\n  color: #e2e8f0;\n  margin-top: 2px;\n}\n\n/* ==================== 4. BUTTONS & BADGES ==================== */\n.btn {\n  padding: 10px 18px;\n  border-radius: 10px;\n  font-size: 13.5px;\n  font-weight: 600;\n  border: none;\n  cursor: pointer;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  transition: all 0.16s ease;\n}\n\n.btn-primary {\n  background: var(--primary);\n  color: #ffffff;\n}\n\n.btn-primary:hover {\n  background: var(--primary-dark);\n}\n\n.btn-secondary {\n  background: #0f172a;\n  color: #ffffff;\n}\n\n.btn-secondary:hover {\n  background: #1e293b;\n}\n\n.btn-outline {\n  background: #ffffff;\n  border: 1.5px solid #cbd5e1;\n  color: #1e293b;\n}\n\n.btn-outline:hover {\n  border-color: #94a3b8;\n  background: #f8fafc;\n}\n\n.btn-light-solid {\n  background: #ffffff;\n  color: #0f172a;\n  font-weight: 700;\n}\n\n.btn-light-solid:hover {\n  background: #eff6ff;\n}\n\n.btn-glass {\n  background: rgba(255, 255, 255, 0.14);\n  color: #ffffff;\n  border: 1px solid rgba(255, 255, 255, 0.28);\n}\n\n.btn-glass:hover {\n  background: rgba(255, 255, 255, 0.24);\n}\n\n.btn-success {\n  background: #10b981;\n  color: #ffffff;\n}\n\n.btn-warn {\n  background: #f59e0b;\n  color: #ffffff;\n}\n\n.btn-danger {\n  background: #ef4444;\n  color: #ffffff;\n}\n\n.btn-sm {\n  padding: 7px 12px;\n  font-size: 12.5px;\n}\n\n.btn-lg {\n  padding: 13px 22px;\n  font-size: 15px;\n}\n\n.btn-block {\n  width: 100%;\n}\n\n.btn-chip {\n  padding: 6px 11px;\n  font-size: 12px;\n  font-weight: 600;\n  border-radius: 8px;\n  border: 1px solid #bfdbfe;\n  background: #eff6ff;\n  color: #1d4ed8;\n  cursor: pointer;\n}\n\n.btn-chip:hover {\n  background: #dbeafe;\n}\n\n/* ==================== 5. SECTIONS, MATCHES & REPORTS GRID ==================== */\n.section-block {\n  margin-top: 34px;\n}\n\n.section-header {\n  display: flex;\n  align-items: flex-end;\n  justify-content: space-between;\n  margin-bottom: 18px;\n}\n\n.section-header h2 {\n  font-size: 21px;\n  font-weight: 800;\n  color: #0f172a;\n}\n\n.section-header p {\n  font-size: 13.5px;\n  color: var(--text-muted);\n}\n\n.matches-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(520px, 1fr));\n  gap: 20px;\n}\n\n.match-card {\n  background: #ffffff;\n  border: 2px solid #93c5fd;\n  border-radius: 18px;\n  padding: 20px;\n  box-shadow: var(--shadow-md);\n  position: relative;\n}\n\n.match-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 14px;\n}\n\n.match-score-pill {\n  background: linear-gradient(135deg, #2563eb, #4f46e5);\n  color: #ffffff;\n  font-weight: 800;\n  font-size: 13px;\n  padding: 5px 12px;\n  border-radius: 999px;\n  display: inline-flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.match-speed-tag {\n  font-size: 12px;\n  color: #059669;\n  font-weight: 700;\n  background: #d1fae5;\n  padding: 4px 10px;\n  border-radius: 999px;\n}\n\n.match-compare-row {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 14px;\n}\n\n.match-side {\n  background: #f8fafc;\n  border: 1px solid var(--border);\n  border-radius: 12px;\n  padding: 12px;\n}\n\n.match-side-title {\n  font-size: 11px;\n  font-weight: 800;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  margin-bottom: 6px;\n  display: block;\n}\n\n.match-tags-row {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  margin-top: 14px;\n}\n\n.match-attr-tag {\n  font-size: 11.5px;\n  font-weight: 600;\n  background: #eff6ff;\n  color: #1e40af;\n  border: 1px solid #bfdbfe;\n  padding: 3px 9px;\n  border-radius: 6px;\n}\n\n.match-footer {\n  margin-top: 16px;\n  padding-top: 14px;\n  border-top: 1px solid var(--border);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n/* Reports Grid */\n.reports-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));\n  gap: 20px;\n}\n\n.report-card {\n  background: var(--bg-card);\n  border: 1px solid var(--border);\n  border-radius: 16px;\n  overflow: hidden;\n  box-shadow: var(--shadow-sm);\n  display: flex;\n  flex-direction: column;\n  transition: transform 0.16s ease, box-shadow 0.16s ease;\n}\n\n.report-card:hover {\n  transform: translateY(-3px);\n  box-shadow: var(--shadow-md);\n}\n\n.report-card.suspicious-card {\n  border: 2px solid #f59e0b;\n}\n\n.report-img-wrap {\n  position: relative;\n  height: 195px;\n  background: #0f172a;\n  overflow: hidden;\n}\n\n.report-img-wrap img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  transition: filter 0.25s ease;\n}\n\n/* PRIVACY BLUR FOR FOUND ITEMS (Requirement #3) */\n.report-img-wrap.privacy-blurred img {\n  filter: blur(14px) scale(1.08);\n}\n\n.privacy-blur-overlay {\n  position: absolute;\n  inset: 0;\n  background: rgba(15, 23, 42, 0.42);\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  text-align: center;\n  padding: 16px;\n  color: #ffffff;\n}\n\n.privacy-blur-pill {\n  background: rgba(15, 23, 42, 0.85);\n  border: 1px solid rgba(56, 189, 248, 0.6);\n  color: #e0f2fe;\n  padding: 6px 12px;\n  border-radius: 999px;\n  font-size: 12px;\n  font-weight: 700;\n  margin-bottom: 4px;\n}\n\n.privacy-blur-sub {\n  font-size: 11px;\n  color: #cbd5e1;\n  max-width: 240px;\n}\n\n.report-badges-top {\n  position: absolute;\n  top: 12px;\n  left: 12px;\n  right: 12px;\n  display: flex;\n  justify-content: space-between;\n  z-index: 2;\n}\n\n.type-badge {\n  padding: 4px 10px;\n  border-radius: 999px;\n  font-size: 11px;\n  font-weight: 800;\n  letter-spacing: 0.04em;\n}\n\n.type-badge.LOST {\n  background: #ef4444;\n  color: #ffffff;\n}\n\n.type-badge.FOUND {\n  background: #10b981;\n  color: #ffffff;\n}\n\n.status-badge {\n  padding: 4px 10px;\n  border-radius: 999px;\n  font-size: 11px;\n  font-weight: 700;\n  background: rgba(15, 23, 42, 0.82);\n  color: #ffffff;\n}\n\n.report-body {\n  padding: 18px;\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  justify-content: space-between;\n}\n\n.report-title {\n  font-size: 16.5px;\n  font-weight: 800;\n  color: #0f172a;\n}\n\n.report-meta-tags {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  margin-top: 8px;\n}\n\n.meta-pill {\n  font-size: 11.5px;\n  background: #f1f5f9;\n  color: #334155;\n  padding: 3px 9px;\n  border-radius: 6px;\n  font-weight: 600;\n}\n\n.report-desc {\n  font-size: 13px;\n  color: #475569;\n  margin-top: 10px;\n}\n\n.report-marks-box {\n  margin-top: 10px;\n  padding: 8px 10px;\n  background: #f8fafc;\n  border-left: 3px solid #3b82f6;\n  border-radius: 6px;\n  font-size: 12px;\n  color: #334155;\n}\n\n.report-footer {\n  margin-top: 16px;\n  padding-top: 12px;\n  border-top: 1px solid var(--border);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 8px;\n}\n\n.reporter-privacy-tag {\n  font-size: 11.5px;\n  color: #64748b;\n}\n\n/* ==================== 6. SEARCH & FILTER BAR ==================== */\n.page-title-bar {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  margin-bottom: 20px;\n}\n\n.filter-bar {\n  background: #ffffff;\n  border: 1px solid var(--border);\n  border-radius: 16px;\n  padding: 18px;\n  margin-bottom: 24px;\n  display: grid;\n  grid-template-columns: 1.6fr repeat(4, 1fr) auto;\n  gap: 12px;\n  box-shadow: var(--shadow-sm);\n}\n\n.filter-group {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}\n\n.filter-group label {\n  font-size: 11.5px;\n  font-weight: 700;\n  color: #475569;\n  text-transform: uppercase;\n}\n\n.filter-group input,\n.filter-group select {\n  padding: 9px 11px;\n  border-radius: 9px;\n  border: 1px solid #cbd5e1;\n  font-size: 13px;\n}\n\n/* ==================== 7. REPORT FORM ==================== */\n.form-card-wrapper {\n  max-width: 840px;\n  margin: 0 auto;\n  background: #ffffff;\n  border: 1px solid var(--border);\n  border-radius: 20px;\n  overflow: hidden;\n  box-shadow: var(--shadow-md);\n}\n\n.report-type-switcher {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  background: #f8fafc;\n  border-bottom: 1px solid var(--border);\n}\n\n.type-switch-btn {\n  padding: 18px 20px;\n  border: none;\n  background: transparent;\n  cursor: pointer;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  font-size: 15px;\n  font-weight: 800;\n  color: #64748b;\n  transition: all 0.16s;\n}\n\n.type-switch-btn span {\n  font-size: 12px;\n  font-weight: 500;\n  margin-top: 2px;\n}\n\n.type-switch-btn.active-lost {\n  background: #fef2f2;\n  color: #dc2626;\n  border-bottom: 3px solid #dc2626;\n}\n\n.type-switch-btn.active-found {\n  background: #ecfdf5;\n  color: #059669;\n  border-bottom: 3px solid #059669;\n}\n\n.report-form {\n  padding: 28px 32px;\n  display: flex;\n  flex-direction: column;\n  gap: 18px;\n}\n\n.form-banner-info {\n  background: #eff6ff;\n  border: 1px solid #bfdbfe;\n  color: #1e3a8a;\n  padding: 12px 16px;\n  border-radius: 10px;\n  font-size: 13.5px;\n}\n\n.preset-autofill-bar {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 8px;\n  padding: 10px 14px;\n  background: #f8fafc;\n  border: 1px dashed #cbd5e1;\n  border-radius: 10px;\n  font-size: 12.5px;\n  font-weight: 600;\n  color: #475569;\n}\n\n.form-grid-2 {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 16px;\n}\n\n.handover-checkbox-box {\n  background: #ecfdf5;\n  border: 1px solid #a7f3d0;\n  padding: 14px 16px;\n  border-radius: 12px;\n}\n\n.checkbox-label {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  font-size: 13.5px;\n  color: #065f46;\n  cursor: pointer;\n}\n\n.photo-upload-zone {\n  display: grid;\n  grid-template-columns: 1.4fr 0.8fr;\n  gap: 16px;\n  padding: 16px;\n  border: 1.5px dashed #cbd5e1;\n  border-radius: 14px;\n  background: #f8fafc;\n  align-items: center;\n}\n\n.preset-photo-selector {\n  margin-top: 10px;\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n  align-items: center;\n  font-size: 12px;\n  color: #64748b;\n}\n\n.compression-badge {\n  margin-top: 10px;\n  font-size: 12px;\n  color: #059669;\n  background: #d1fae5;\n  padding: 6px 10px;\n  border-radius: 8px;\n  display: inline-block;\n}\n\n.photo-preview-box {\n  height: 140px;\n  border-radius: 10px;\n  overflow: hidden;\n  background: #0f172a;\n  border: 1px solid #cbd5e1;\n}\n\n.photo-preview-box img {\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n\n/* ==================== 8. CLAIMS LIST & STATUS CARDS ==================== */\n.claims-list {\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n.claim-card {\n  background: #ffffff;\n  border: 1px solid var(--border);\n  border-radius: 16px;\n  padding: 20px;\n  box-shadow: var(--shadow-sm);\n}\n\n.claim-card-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding-bottom: 14px;\n  border-bottom: 1px solid var(--border);\n}\n\n.claim-status-pill {\n  padding: 5px 12px;\n  border-radius: 999px;\n  font-size: 12px;\n  font-weight: 800;\n}\n\n.claim-status-pill.Pending {\n  background: #fef3c7;\n  color: #b45309;\n}\n\n.claim-status-pill.MoreProof {\n  background: #ffedd5;\n  color: #c2410c;\n  border: 1px solid #fb923c;\n}\n\n.claim-status-pill.Approved {\n  background: #dbeafe;\n  color: #1d4ed8;\n}\n\n.claim-status-pill.Returned {\n  background: #d1fae5;\n  color: #047857;\n}\n\n.claim-status-pill.Rejected,\n.claim-status-pill.Hold {\n  background: #fee2e2;\n  color: #b91c1c;\n}\n\n.claim-comparison-grid {\n  margin-top: 16px;\n  display: grid;\n  grid-template-columns: repeat(3, 1fr);\n  gap: 14px;\n}\n\n.claim-col {\n  background: #f8fafc;\n  border: 1px solid var(--border);\n  border-radius: 12px;\n  padding: 12px;\n}\n\n.claim-col h5 {\n  font-size: 11.5px;\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n  color: #475569;\n  margin-bottom: 8px;\n}\n\n.claim-col img {\n  width: 100%;\n  height: 125px;\n  object-fit: cover;\n  border-radius: 8px;\n  margin-bottom: 8px;\n}\n\n/* ==================== 9. FLOATING BOTTOM-RIGHT DEVOPS / ADMIN BUTTON ==================== */\n.devops-fab {\n  position: fixed;\n  bottom: 24px;\n  right: 24px;\n  z-index: 950;\n  background: linear-gradient(135deg, #06122e 0%, #0d255c 55%, #1d4ed8 100%);\n  color: #ffffff;\n  border: 1.5px solid #38bdf8;\n  border-radius: 999px;\n  padding: 12px 22px;\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  cursor: pointer;\n  box-shadow: 0 14px 35px rgba(2, 12, 36, 0.65), 0 0 20px rgba(56, 189, 248, 0.35);\n  transition: transform 0.2s ease, box-shadow 0.2s ease;\n}\n\n.devops-fab:hover {\n  transform: translateY(-3px) scale(1.02);\n  box-shadow: 0 18px 42px rgba(2, 12, 36, 0.8), 0 0 28px rgba(56, 189, 248, 0.6);\n}\n\n.devops-fab-icon {\n  font-size: 20px;\n}\n\n.devops-fab-text {\n  display: flex;\n  flex-direction: column;\n  text-align: left;\n  line-height: 1.15;\n}\n\n.devops-fab-text strong {\n  font-size: 13.5px;\n  color: #f8fafc;\n}\n\n.devops-fab-text span {\n  font-size: 11px;\n  color: #7dd3fc;\n}\n\n.devops-fab-badge {\n  background: #f59e0b;\n  color: #0f172a;\n  font-weight: 800;\n  font-size: 11.5px;\n  padding: 2px 8px;\n  border-radius: 999px;\n}\n\n/* ==================== 10. COOL DARK-BLUE TINTED DEVOPS & ADMIN OVERLAY ==================== */\n.devops-overlay {\n  position: fixed;\n  inset: 0;\n  z-index: 1000;\n  background: rgba(3, 9, 24, 0.82);\n  backdrop-filter: blur(12px);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 24px;\n}\n\n.devops-console {\n  width: 100%;\n  max-width: 1240px;\n  height: 90vh;\n  background: linear-gradient(160deg, #050d21 0%, #09193a 55%, #061229 100%);\n  border: 1.5px solid rgba(56, 189, 248, 0.4);\n  border-radius: 22px;\n  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.85), 0 0 45px rgba(37, 99, 235, 0.3);\n  color: #e2e8f0;\n  display: flex;\n  flex-direction: column;\n  overflow: hidden;\n}\n\n.devops-header {\n  padding: 22px 28px;\n  background: rgba(4, 12, 32, 0.75);\n  border-bottom: 1px solid rgba(56, 189, 248, 0.22);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.devops-chip {\n  display: inline-block;\n  font-size: 10.5px;\n  font-weight: 800;\n  letter-spacing: 0.08em;\n  color: #38bdf8;\n  background: rgba(56, 189, 248, 0.14);\n  border: 1px solid rgba(56, 189, 248, 0.35);\n  padding: 3px 10px;\n  border-radius: 999px;\n  margin-bottom: 4px;\n}\n\n.devops-title-group h2 {\n  font-size: 22px;\n  font-weight: 800;\n  color: #ffffff;\n}\n\n.devops-title-group p {\n  font-size: 13px;\n  color: #93c5fd;\n}\n\n.devops-close-btn {\n  padding: 9px 16px;\n  border-radius: 10px;\n  border: 1px solid rgba(148, 163, 184, 0.35);\n  background: rgba(15, 23, 42, 0.8);\n  color: #f8fafc;\n  font-weight: 700;\n  cursor: pointer;\n}\n\n.devops-close-btn:hover {\n  border-color: #38bdf8;\n  color: #38bdf8;\n}\n\n.devops-quickbar {\n  padding: 14px 28px;\n  background: rgba(10, 25, 58, 0.75);\n  border-bottom: 1px solid rgba(56, 189, 248, 0.2);\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 16px;\n}\n\n.devops-quick-group {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n\n.quick-title {\n  font-size: 12px;\n  font-weight: 700;\n  color: #7dd3fc;\n  text-transform: uppercase;\n}\n\n.devops-user-pills,\n.devops-scenario-btns {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n\n.devops-btn {\n  padding: 7px 13px;\n  border-radius: 9px;\n  border: 1px solid rgba(96, 165, 250, 0.35);\n  background: rgba(15, 32, 72, 0.85);\n  color: #e0f2fe;\n  font-size: 12px;\n  font-weight: 600;\n  cursor: pointer;\n  transition: all 0.15s;\n}\n\n.devops-btn:hover,\n.devops-btn.active-persona {\n  background: #2563eb;\n  border-color: #60a5fa;\n  color: #ffffff;\n}\n\n.devops-btn-cyan {\n  background: rgba(14, 116, 144, 0.65);\n  border-color: #38bdf8;\n}\n\n.devops-tabs {\n  display: flex;\n  gap: 8px;\n  padding: 12px 28px 0;\n  background: rgba(6, 15, 36, 0.6);\n  border-bottom: 1px solid rgba(56, 189, 248, 0.22);\n}\n\n.devops-tab {\n  padding: 11px 18px;\n  border: 1px solid transparent;\n  border-bottom: none;\n  border-radius: 12px 12px 0 0;\n  background: transparent;\n  color: #94a3b8;\n  font-size: 13px;\n  font-weight: 700;\n  cursor: pointer;\n  display: inline-flex;\n  align-items: center;\n  gap: 8px;\n}\n\n.devops-tab.active {\n  background: rgba(14, 34, 78, 0.95);\n  border-color: rgba(56, 189, 248, 0.35);\n  color: #38bdf8;\n}\n\n.dtab-badge {\n  background: rgba(56, 189, 248, 0.2);\n  color: #38bdf8;\n  padding: 1px 8px;\n  border-radius: 99px;\n  font-size: 11px;\n}\n\n.devops-body {\n  padding: 24px 28px;\n  overflow-y: auto;\n  flex: 1;\n}\n\n.devops-claim-card {\n  background: rgba(11, 27, 61, 0.85);\n  border: 1px solid rgba(56, 189, 248, 0.28);\n  border-radius: 16px;\n  padding: 20px;\n  margin-bottom: 18px;\n}\n\n.devops-claim-card .claim-col {\n  background: rgba(6, 16, 38, 0.85);\n  border-color: rgba(56, 189, 248, 0.2);\n  color: #e2e8f0;\n}\n\n.devops-claim-card .claim-col h5 {\n  color: #7dd3fc;\n}\n\n.devops-action-bar {\n  margin-top: 16px;\n  padding-top: 14px;\n  border-top: 1px solid rgba(56, 189, 248, 0.2);\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  justify-content: space-between;\n  gap: 12px;\n}\n\n.devops-feedback-input {\n  flex: 1;\n  min-width: 260px;\n  padding: 9px 13px;\n  border-radius: 9px;\n  border: 1px solid rgba(56, 189, 248, 0.35);\n  background: rgba(4, 11, 28, 0.9);\n  color: #f8fafc;\n  font-size: 13px;\n}\n\n.devops-panel-intro {\n  background: rgba(14, 38, 86, 0.7);\n  border: 1px solid rgba(56, 189, 248, 0.3);\n  padding: 14px 18px;\n  border-radius: 12px;\n  font-size: 13px;\n  color: #bae6fd;\n  margin-bottom: 18px;\n}\n\n.devops-mod-grid {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(380px, 1fr));\n  gap: 18px;\n}\n\n.devops-mod-card {\n  background: rgba(11, 27, 61, 0.9);\n  border: 1px solid rgba(245, 158, 11, 0.45);\n  border-radius: 14px;\n  padding: 18px;\n}\n\n.devops-telemetry-grid {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 18px;\n}\n\n.telemetry-card {\n  background: rgba(10, 24, 54, 0.85);\n  border: 1px solid rgba(56, 189, 248, 0.25);\n  border-radius: 14px;\n  padding: 18px;\n}\n\n.telemetry-card h4 {\n  color: #38bdf8;\n  font-size: 14px;\n  margin-bottom: 12px;\n}\n\n.nfr-status-list {\n  list-style: none;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  font-size: 13px;\n}\n\n.nfr-status-list li {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  padding: 8px 12px;\n  background: rgba(5, 13, 33, 0.75);\n  border-radius: 8px;\n}\n\n.devops-terminal {\n  background: #030712;\n  border: 1px solid rgba(56, 189, 248, 0.25);\n  border-radius: 10px;\n  padding: 14px;\n  font-family: 'Consolas', 'Courier New', monospace;\n  font-size: 12px;\n  max-height: 230px;\n  overflow-y: auto;\n  color: #38bdf8;\n}\n\n.log-line {\n  padding: 4px 0;\n  border-bottom: 1px solid rgba(255, 255, 255, 0.05);\n}\n\n.mt-16 {\n  margin-top: 16px;\n}\n\n/* ==================== 11. MODALS, DRAWER & TOASTS ==================== */\n.modal-backdrop {\n  position: fixed;\n  inset: 0;\n  z-index: 980;\n  background: rgba(15, 23, 42, 0.65);\n  backdrop-filter: blur(6px);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  padding: 20px;\n}\n\n.modal-card {\n  width: 100%;\n  max-width: 620px;\n  background: #ffffff;\n  border-radius: 18px;\n  overflow: hidden;\n  box-shadow: var(--shadow-lg);\n}\n\n.modal-header {\n  padding: 20px 24px;\n  background: #f8fafc;\n  border-bottom: 1px solid var(--border);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.modal-body {\n  padding: 22px 24px;\n  display: flex;\n  flex-direction: column;\n  gap: 16px;\n}\n\n.modal-footer {\n  display: flex;\n  justify-content: flex-end;\n  gap: 10px;\n  padding-top: 10px;\n}\n\n.close-btn {\n  border: none;\n  background: #e2e8f0;\n  width: 32px;\n  height: 32px;\n  border-radius: 8px;\n  cursor: pointer;\n  font-weight: 700;\n}\n\n.notif-drawer {\n  position: fixed;\n  top: 70px;\n  right: 0;\n  bottom: 0;\n  width: 400px;\n  max-width: 92vw;\n  background: #ffffff;\n  border-left: 1px solid var(--border);\n  box-shadow: -12px 0 35px rgba(15, 23, 42, 0.14);\n  z-index: 900;\n  display: flex;\n  flex-direction: column;\n}\n\n.notif-drawer-header {\n  padding: 18px 20px;\n  border-bottom: 1px solid var(--border);\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.notif-drawer-body {\n  padding: 16px;\n  overflow-y: auto;\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.notif-item {\n  padding: 13px 14px;\n  border-radius: 12px;\n  border: 1px solid var(--border);\n  background: #f8fafc;\n}\n\n.notif-item.unread {\n  background: #eff6ff;\n  border-color: #93c5fd;\n}\n\n.notif-item h5 {\n  font-size: 13.5px;\n  color: #0f172a;\n}\n\n.notif-item p {\n  font-size: 12.5px;\n  color: #475569;\n  margin-top: 4px;\n}\n\n.alert-box {\n  padding: 12px 14px;\n  border-radius: 10px;\n  font-size: 13px;\n}\n\n.alert-error {\n  background: #fee2e2;\n  color: #b91c1c;\n  border: 1px solid #fca5a5;\n}\n\n.alert-warn {\n  background: #fef3c7;\n  color: #92400e;\n  border: 1px solid #fcd34d;\n}\n\n.admin-workspace-banner {\n  background: linear-gradient(135deg, #071330, #1e3a8a);\n  color: #fff;\n  padding: 28px 32px;\n  border-radius: 18px;\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 20px;\n}\n\n.admin-pill {\n  font-size: 11px;\n  font-weight: 800;\n  color: #38bdf8;\n  letter-spacing: 0.06em;\n}\n\n.btn-devops-trigger {\n  background: #38bdf8;\n  color: #0f172a;\n  font-weight: 800;\n}\n\n.toast-container {\n  position: fixed;\n  top: 84px;\n  right: 24px;\n  z-index: 1100;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.toast {\n  background: #0f172a;\n  color: #ffffff;\n  border-left: 4px solid #38bdf8;\n  padding: 13px 18px;\n  border-radius: 10px;\n  box-shadow: var(--shadow-lg);\n  font-size: 13.5px;\n  max-width: 380px;\n}\n\n/* Responsive adjustments (Mobile-Responsive Usability NFR) */\n@media (max-width: 960px) {\n  .login-container,\n  .hero-banner,\n  .filter-bar,\n  .claim-comparison-grid,\n  .devops-telemetry-grid {\n    grid-template-columns: 1fr;\n  }\n  .matches-grid {\n    grid-template-columns: 1fr;\n  }\n  .top-navbar {\n    height: auto;\n    padding: 12px 16px;\n    flex-direction: column;\n    gap: 10px;\n  }\n  .main-nav {\n    flex-wrap: wrap;\n    justify-content: center;\n  }\n}\n\n","/app.js":"// Automatically resolve API base:\n// When running locally on port 3000 with backend on 5000, target port 5000.\n// When deployed on Vercel or under 'vercel dev' (with top-level rewrites /api/*), use relative '/api'.\nconst API_BASE = (window.location.hostname === 'localhost' && window.location.port === '3000')\n  ? 'http://localhost:5000/api'\n  : '/api';\n\n// Application State\nlet currentUser = null;\nlet appHealth = null;\nlet allReports = [];\nlet allMatches = [];\nlet allClaims = [];\nlet userNotifications = [];\nlet presetImages = {};\n\n// Current uploaded/selected photo state\nlet reportPhotoDataUrl = '';\nlet reportPhotoSizeKb = 192.4;\nlet claimPhotoDataUrl = '';\n\n// Initialize App\nwindow.addEventListener('DOMContentLoaded', async () => {\n  const savedUser = localStorage.getItem('reclaim_user');\n  if (savedUser) {\n    try {\n      currentUser = JSON.parse(savedUser);\n    } catch {\n      currentUser = null;\n    }\n  }\n\n  await fetchHealthAndPresets();\n\n  if (currentUser) {\n    enterAppShell();\n  }\n\n  // Bind Login Form\n  document.getElementById('login-form').addEventListener('submit', handleLoginSubmit);\n\n  // Bind Create Report Form\n  document.getElementById('create-report-form').addEventListener('submit', handleCreateReportSubmit);\n\n  // Bind Submit Claim Form\n  document.getElementById('submit-claim-form').addEventListener('submit', handleSubmitClaim);\n\n  // Bind More Proof Form\n  document.getElementById('more-proof-form').addEventListener('submit', handleMoreProofSubmit);\n});\n\nasync function apiRequest(path, options = {}) {\n  const res = await fetch(`${API_BASE}${path}`, {\n    headers: { 'Content-Type': 'application/json' },\n    ...options\n  });\n  const data = await res.json();\n  if (!res.ok) {\n    throw new Error(data.error || 'Request failed');\n  }\n  return data;\n}\n\nfunction showToast(message) {\n  const container = document.getElementById('toast-container');\n  const toast = document.createElement('div');\n  toast.className = 'toast';\n  toast.innerHTML = message;\n  container.appendChild(toast);\n  setTimeout(() => {\n    toast.remove();\n  }, 4200);\n}\n\nasync function fetchHealthAndPresets() {\n  try {\n    appHealth = await apiRequest('/health');\n    presetImages = appHealth.presets || {};\n    if (!reportPhotoDataUrl && presetImages.charger_lost) {\n      reportPhotoDataUrl = presetImages.charger_lost;\n      const preview = document.getElementById('rep-photo-preview');\n      if (preview) preview.src = reportPhotoDataUrl;\n    }\n    if (!claimPhotoDataUrl && presetImages.charger_proof) {\n      claimPhotoDataUrl = presetImages.charger_proof;\n      const cPreview = document.getElementById('claim-photo-preview');\n      if (cPreview) cPreview.src = claimPhotoDataUrl;\n    }\n    renderDevOpsConsole();\n  } catch (err) {\n    console.error('Could not reach backend API at localhost:5000:', err);\n  }\n}\n\n// ==================== 1. UNIFIED LOGIN (AUTO-CREATE & REMEMBER) ====================\nfunction quickFillLogin(username, password) {\n  document.getElementById('login-username').value = username;\n  document.getElementById('login-password').value = password;\n  document.getElementById('login-form').requestSubmit();\n}\n\nasync function handleLoginSubmit(e) {\n  e.preventDefault();\n  const errBox = document.getElementById('login-error');\n  errBox.classList.add('hidden');\n\n  const username = document.getElementById('login-username').value.trim();\n  const password = document.getElementById('login-password').value.trim();\n\n  try {\n    const data = await apiRequest('/login', {\n      method: 'POST',\n      body: JSON.stringify({ username, password })\n    });\n\n    currentUser = data.user;\n    localStorage.setItem('reclaim_user', JSON.stringify(currentUser));\n\n    if (data.isNewAccount) {\n      showToast(`✨ New account <strong>@${currentUser.username}</strong> auto-created &amp; saved in SQLite!`);\n    } else {\n      showToast(`👋 Welcome back, <strong>@${currentUser.username}</strong> (${currentUser.role.toUpperCase()})`);\n    }\n\n    await enterAppShell();\n  } catch (err) {\n    errBox.textContent = err.message;\n    errBox.classList.remove('hidden');\n  }\n}\n\nfunction handleLogout() {\n  currentUser = null;\n  localStorage.removeItem('reclaim_user');\n  document.getElementById('app-shell').classList.add('hidden');\n  document.getElementById('login-screen').classList.remove('hidden');\n  document.getElementById('login-password').value = '';\n  showToast('Signed out of Reclaim.');\n}\n\nasync function enterAppShell() {\n  document.getElementById('login-screen').classList.add('hidden');\n  document.getElementById('app-shell').classList.remove('hidden');\n\n  updateUserHeader();\n  await refreshAllData();\n  if (currentUser.role === 'admin') {\n    switchView('admin');\n  } else {\n    switchView('home');\n  }\n}\n\nfunction updateUserHeader() {\n  if (!currentUser) return;\n  document.getElementById('header-user-avatar').textContent = currentUser.username.charAt(0).toUpperCase();\n  document.getElementById('header-username').textContent = `@${currentUser.username}`;\n  document.getElementById('header-user-role').textContent =\n    currentUser.role === 'admin' ? '🛡️ Administrator' : '🎓 Student';\n\n  const adminTab = document.getElementById('nav-admin-tab');\n  if (currentUser.role === 'admin') {\n    adminTab.classList.remove('hidden');\n  } else {\n    adminTab.classList.add('hidden');\n  }\n\n  document.getElementById('welcome-headline').textContent = `Welcome back, ${currentUser.display_name}`;\n}\n\n// ==================== 2. REFRESH ALL DATA FROM SQLITE BACKEND ====================\nasync function refreshAllData() {\n  if (!currentUser) return;\n\n  try {\n    const [healthRes, reportsRes, matchesRes, claimsRes, notifsRes] = await Promise.all([\n      apiRequest('/health'),\n      apiRequest(`/reports?viewerRole=${encodeURIComponent(currentUser.role)}&viewerUsername=${encodeURIComponent(currentUser.username)}`),\n      apiRequest(`/matches?username=${encodeURIComponent(currentUser.username)}&role=${encodeURIComponent(currentUser.role)}`),\n      apiRequest('/claims'),\n      apiRequest(`/notifications?username=${encodeURIComponent(currentUser.username)}`)\n    ]);\n\n    appHealth = healthRes;\n    presetImages = healthRes.presets || presetImages;\n    allReports = reportsRes.reports || [];\n    allMatches = matchesRes.matches || [];\n    allClaims = claimsRes.claims || [];\n    userNotifications = notifsRes.notifications || [];\n\n    renderStatsAndBadges();\n    renderHomeView();\n    applySearchFilters();\n    renderClaimsAndMatchesView();\n    renderAdminWorkspaceView();\n    renderNotificationsDrawer();\n    renderDevOpsConsole();\n  } catch (err) {\n    console.error('Error refreshing data:', err);\n  }\n}\n\nfunction renderStatsAndBadges() {\n  if (!appHealth) return;\n  document.getElementById('stat-total-reports').textContent = appHealth.counts.reports;\n  document.getElementById('stat-total-matches').textContent = appHealth.counts.matches;\n  document.getElementById('stat-match-speed').textContent = `${appHealth.nfr.lastMatchLatencyMs} ms`;\n  document.getElementById('stat-resolved-cases').textContent = appHealth.counts.resolvedCases;\n\n  // Unread notifications badge\n  const unreadCount = userNotifications.filter((n) => !n.is_read).length;\n  const notifBadge = document.getElementById('notif-unread-badge');\n  if (unreadCount > 0) {\n    notifBadge.textContent = unreadCount;\n    notifBadge.classList.remove('hidden');\n  } else {\n    notifBadge.classList.add('hidden');\n  }\n\n  // Pending claims / matches badge\n  const pendingClaimsCount = appHealth.counts.pendingClaims;\n  const adminBadge = document.getElementById('nav-admin-badge');\n  if (adminBadge) adminBadge.textContent = pendingClaimsCount + appHealth.counts.suspiciousReports;\n\n  const fabBadge = document.getElementById('devops-fab-badge');\n  if (fabBadge) fabBadge.textContent = pendingClaimsCount + appHealth.counts.suspiciousReports;\n\n  const myClaimsCount = allClaims.filter((c) => c.claimant_username.toLowerCase() === currentUser.username.toLowerCase()).length;\n  const navClaimsBadge = document.getElementById('nav-claims-badge');\n  if (myClaimsCount + allMatches.length > 0) {\n    navClaimsBadge.textContent = myClaimsCount + allMatches.length;\n    navClaimsBadge.classList.remove('hidden');\n  } else {\n    navClaimsBadge.classList.add('hidden');\n  }\n}\n\n// ==================== 3. VIEW NAVIGATION ====================\nfunction switchView(viewName) {\n  document.querySelectorAll('.view-section').forEach((el) => el.classList.add('hidden'));\n  const target = document.getElementById(`view-${viewName}`);\n  if (target) target.classList.remove('hidden');\n\n  document.querySelectorAll('.nav-btn').forEach((btn) => {\n    btn.classList.toggle('active', btn.dataset.view === viewName);\n  });\n}\n\nfunction openReportForm(type) {\n  switchView('report');\n  setReportFormType(type);\n}\n\n// ==================== 4. RENDER MATCHES & REPORTS ====================\nfunction buildMatchCardHtml(match) {\n  const blurClass = match.found_should_blur ? 'privacy-blurred' : '';\n  const tagsHtml = (match.matched_attributes || [])\n    .map((t) => `<span class=\"match-attr-tag\">✓ ${escapeHtml(t)}</span>`)\n    .join('');\n\n  return `\n    <div class=\"match-card\">\n      <div class=\"match-header\">\n        <span class=\"match-score-pill\">⚡ ${match.score}% Automated Match</span>\n        <span class=\"match-speed-tag\">Matched in ${match.match_time_ms} ms (&lt;3s NFR)</span>\n      </div>\n\n      <div class=\"match-compare-row\">\n        <div class=\"match-side\">\n          <span class=\"match-side-title\" style=\"color:#dc2626;\">📢 Lost Report (#${match.lost_report_id})</span>\n          <strong>${escapeHtml(match.lost_title)}</strong>\n          <div style=\"font-size:12px;color:#475569;margin-top:4px;\">\n            📍 ${escapeHtml(match.lost_location)} • ${escapeHtml(match.lost_color)} • ${escapeHtml(match.lost_brand || 'N/A')}\n          </div>\n        </div>\n\n        <div class=\"match-side\">\n          <span class=\"match-side-title\" style=\"color:#059669;\">📦 Found Report (#${match.found_report_id})</span>\n          <strong>${escapeHtml(match.found_title)}</strong>\n          <div style=\"font-size:12px;color:#475569;margin-top:4px;\">\n            📍 ${escapeHtml(match.found_location)} • ${escapeHtml(match.found_color)}\n            ${match.found_should_blur ? '<span style=\"color:#0284c7;font-weight:700;\">(Photo Blurred)</span>' : ''}\n          </div>\n        </div>\n      </div>\n\n      <div class=\"match-tags-row\">${tagsHtml}</div>\n\n      <div class=\"match-footer\">\n        <span style=\"font-size:12px;color:#64748b;\">\n          Status: <strong>${escapeHtml(match.found_status)}</strong>\n        </span>\n        <div style=\"display:flex;gap:8px;\">\n          ${\n            match.found_status === 'Returned' || match.found_status === 'Resolved'\n              ? `<span class=\"btn btn-sm\" style=\"background:#d1fae5;color:#047857;\">✅ Item Returned &amp; Resolved</span>`\n              : `<button class=\"btn btn-primary btn-sm\" onclick=\"openClaimModal(${match.found_report_id}, ${match.lost_report_id}, '${escapeQuotes(match.found_title)}')\">\n                   🛡️ Submit Ownership Claim\n                 </button>`\n          }\n        </div>\n      </div>\n    </div>\n  `;\n}\n\nfunction buildReportCardHtml(report) {\n  const isBlurred = report.should_blur_photo;\n  const suspiciousBanner = report.is_suspicious\n    ? `<div class=\"alert-box alert-warn\" style=\"margin-top:10px;font-size:11.5px;\">\n         🚨 <strong>Flagged Suspicious:</strong> ${escapeHtml(report.suspicious_reason || 'Under Admin Review')}\n       </div>`\n    : '';\n\n  return `\n    <div class=\"report-card ${report.is_suspicious ? 'suspicious-card' : ''}\">\n      <div class=\"report-img-wrap ${isBlurred ? 'privacy-blurred' : ''}\">\n        <div class=\"report-badges-top\">\n          <span class=\"type-badge ${report.type}\">${report.type === 'LOST' ? '📢 LOST ITEM' : '📦 FOUND ITEM'}</span>\n          <span class=\"status-badge\">${escapeHtml(report.status)}</span>\n        </div>\n        <img src=\"${report.photo_url}\" alt=\"${escapeHtml(report.title)}\" />\n        ${\n          isBlurred\n            ? `<div class=\"privacy-blur-overlay\">\n                 <span class=\"privacy-blur-pill\">🔒 Photo Blurred for Privacy</span>\n                 <span class=\"privacy-blur-sub\">Prevents fraudulent claims. Only Admin &amp; verified owner can view unblurred photo.</span>\n               </div>`\n            : ''\n        }\n      </div>\n\n      <div class=\"report-body\">\n        <div>\n          <h4 class=\"report-title\">${escapeHtml(report.title)}</h4>\n          <div class=\"report-meta-tags\">\n            <span class=\"meta-pill\">📍 ${escapeHtml(report.location)}</span>\n            <span class=\"meta-pill\">🏷️ ${escapeHtml(report.category)}</span>\n            <span class=\"meta-pill\">🎨 ${escapeHtml(report.color)}</span>\n            ${report.brand ? `<span class=\"meta-pill\">✨ ${escapeHtml(report.brand)}</span>` : ''}\n          </div>\n          <p class=\"report-desc\">${escapeHtml(report.description)}</p>\n          <div class=\"report-marks-box\">\n            <strong>Distinguishing Marks:</strong> ${escapeHtml(report.distinguishing_marks_display)}\n          </div>\n          ${suspiciousBanner}\n        </div>\n\n        <div class=\"report-footer\">\n          <span class=\"reporter-privacy-tag\">\n            👤 ${escapeHtml(report.reporter_label)} • ${escapeHtml(report.date_lost_found)}\n          </span>\n          <div style=\"display:flex;gap:6px;\">\n            ${\n              report.type === 'FOUND' && report.status !== 'Returned' && report.status !== 'Resolved'\n                ? `<button class=\"btn btn-primary btn-sm\" onclick=\"openClaimModal(${report.id}, null, '${escapeQuotes(report.title)}')\">\n                     Submit Claim\n                   </button>`\n                : ''\n            }\n            ${\n              !report.is_suspicious\n                ? `<button class=\"btn btn-outline btn-sm\" title=\"Flag as Suspicious / Duplicate (BPMN Fig. 4)\" onclick=\"flagReportSuspicious(${report.id})\">\n                     🚩\n                   </button>`\n                : ''\n            }\n          </div>\n        </div>\n      </div>\n    </div>\n  `;\n}\n\nfunction renderHomeView() {\n  const matchesContainer = document.getElementById('home-matches-container');\n  if (allMatches.length === 0) {\n    matchesContainer.innerHTML = `<div class=\"alert-box\">No automated matches yet. Submit a Lost &amp; Found report pair to see the &lt;3s matching engine in action!</div>`;\n  } else {\n    matchesContainer.innerHTML = allMatches.slice(0, 4).map(buildMatchCardHtml).join('');\n  }\n\n  const reportsContainer = document.getElementById('home-reports-container');\n  const activeReports = allReports.filter((r) => !r.is_suspicious || currentUser.role === 'admin');\n  reportsContainer.innerHTML = activeReports.slice(0, 6).map(buildReportCardHtml).join('');\n}\n\n// ==================== 5. SEARCH & FILTER (Use Case 3 / BPMN Fig. 3) ====================\nfunction applySearchFilters() {\n  const q = (document.getElementById('filter-q')?.value || '').trim().toLowerCase();\n  const type = document.getElementById('filter-type')?.value || 'ALL';\n  const category = document.getElementById('filter-category')?.value || 'ALL';\n  const location = document.getElementById('filter-location')?.value || 'ALL';\n  const color = document.getElementById('filter-color')?.value || 'ALL';\n\n  let filtered = allReports.filter((r) => !r.is_suspicious || currentUser?.role === 'admin');\n\n  if (type !== 'ALL') filtered = filtered.filter((r) => r.type === type);\n  if (category !== 'ALL') filtered = filtered.filter((r) => r.category === category);\n  if (location !== 'ALL') filtered = filtered.filter((r) => r.location === location);\n  if (color !== 'ALL') filtered = filtered.filter((r) => r.color.toLowerCase() === color.toLowerCase());\n  if (q) {\n    filtered = filtered.filter(\n      (r) =>\n        r.title.toLowerCase().includes(q) ||\n        r.description.toLowerCase().includes(q) ||\n        (r.brand || '').toLowerCase().includes(q) ||\n        r.location.toLowerCase().includes(q) ||\n        r.category.toLowerCase().includes(q)\n    );\n  }\n\n  const container = document.getElementById('browse-reports-container');\n  if (filtered.length === 0) {\n    container.innerHTML = `<div class=\"alert-box\">No campus items matched your filter criteria. Try resetting the filters.</div>`;\n  } else {\n    container.innerHTML = filtered.map(buildReportCardHtml).join('');\n  }\n}\n\nfunction resetSearchFilters() {\n  document.getElementById('filter-q').value = '';\n  document.getElementById('filter-type').value = 'ALL';\n  document.getElementById('filter-category').value = 'ALL';\n  document.getElementById('filter-location').value = 'ALL';\n  document.getElementById('filter-color').value = 'ALL';\n  applySearchFilters();\n}\n\n// ==================== 6. REPORT LOST OR FOUND ITEM & NFR IMAGE COMPRESSION ====================\nfunction setReportFormType(type) {\n  document.getElementById('report-type-input').value = type;\n  const lostBtn = document.getElementById('tab-btn-lost');\n  const foundBtn = document.getElementById('tab-btn-found');\n  const banner = document.getElementById('report-form-banner');\n  const handoverBox = document.getElementById('found-handover-box');\n\n  if (type === 'LOST') {\n    lostBtn.className = 'type-switch-btn active-lost';\n    foundBtn.className = 'type-switch-btn';\n    banner.innerHTML = `<strong>Lost Item Report (Use Case 3):</strong> Enter your lost item details and an old photo if available. The automated matching engine will scan found items in &lt; 3 seconds.`;\n    handoverBox.classList.add('hidden');\n    selectPresetPhoto('charger_lost', 'report');\n  } else {\n    lostBtn.className = 'type-switch-btn';\n    foundBtn.className = 'type-switch-btn active-found';\n    banner.innerHTML = `<strong>Found Item Report (Use Case 2 / BPMN Fig. 2):</strong> Upload photo evidence and hand over the physical item to the Lost &amp; Found Office. Note: Your photo will be blurred for students to prevent fake claims!`;\n    handoverBox.classList.remove('hidden');\n    selectPresetPhoto('charger_found', 'report');\n  }\n}\n\nfunction autofillAhmedLostCharger() {\n  setReportFormType('LOST');\n  document.getElementById('rep-title').value = 'Black Laptop Charger (65W USB-C)';\n  document.getElementById('rep-category').value = 'Electronics';\n  document.getElementById('rep-color').value = 'Black';\n  document.getElementById('rep-brand').value = 'Dell';\n  document.getElementById('rep-location').value = 'Engineering Building';\n  document.getElementById('rep-date').value = 'Today, 09:30 AM';\n  document.getElementById('rep-description').value =\n    'Lost my black Dell 65W laptop charger after attending the morning lecture in the Engineering Building. Realized it was missing when I arrived at the library.';\n  document.getElementById('rep-marks').value =\n    'Blue velcro cable strap attached and serial number CN-065W-AH92.';\n  selectPresetPhoto('charger_lost', 'report');\n  showToast('⚡ Auto-filled Ahmed’s Lost Black Laptop Charger details!');\n}\n\nfunction autofillKhalidFoundCharger() {\n  setReportFormType('FOUND');\n  document.getElementById('rep-title').value = 'Black Laptop Charger';\n  document.getElementById('rep-category').value = 'Electronics';\n  document.getElementById('rep-color').value = 'Black';\n  document.getElementById('rep-brand').value = 'Dell';\n  document.getElementById('rep-location').value = 'Engineering Building';\n  document.getElementById('rep-date').value = 'Today, 11:15 AM';\n  document.getElementById('rep-description').value =\n    'Found a black Dell USB-C laptop charger near a desk in the Engineering Building lecture hall. Handing over to Lost & Found Administrator.';\n  document.getElementById('rep-marks').value =\n    'Has a blue velcro strap and serial CN-065W-AH92.';\n  selectPresetPhoto('charger_found', 'report');\n  showToast('⚡ Auto-filled Khalid’s Found Black Laptop Charger details!');\n}\n\nfunction selectPresetPhoto(presetKey, target) {\n  const url = presetImages[presetKey] || presetImages.charger_lost;\n  if (!url) return;\n  if (target === 'report') {\n    reportPhotoDataUrl = url;\n    reportPhotoSizeKb = 186.5;\n    document.getElementById('rep-photo-preview').src = url;\n    document.getElementById('compression-telemetry').innerHTML =\n      `✅ NFR Image Compression Verified: <strong>186.5 KB</strong> / 3,072 KB max (PASS)`;\n  } else {\n    claimPhotoDataUrl = url;\n    document.getElementById('claim-photo-preview').src = url;\n  }\n}\n\n// Client-side Automatic Image Compression (< 3MB NFR)\nfunction handleImageUpload(event, target) {\n  const file = event.target.files?.[0];\n  if (!file) return;\n\n  const originalKb = (file.size / 1024).toFixed(1);\n  const reader = new FileReader();\n  reader.onload = (e) => {\n    const img = new Image();\n    img.onload = () => {\n      const canvas = document.createElement('canvas');\n      const maxDim = 900;\n      let width = img.width;\n      let height = img.height;\n      if (width > maxDim || height > maxDim) {\n        if (width > height) {\n          height = Math.round((height * maxDim) / width);\n          width = maxDim;\n        } else {\n          width = Math.round((width * maxDim) / height);\n          height = maxDim;\n        }\n      }\n      canvas.width = width;\n      canvas.height = height;\n      const ctx = canvas.getContext('2d');\n      ctx.drawImage(img, 0, 0, width, height);\n\n      const compressedDataUrl = canvas.toDataURL('image/jpeg', 0.82);\n      const compressedKb = Number(((compressedDataUrl.length * 0.75) / 1024).toFixed(1));\n\n      if (target === 'report') {\n        reportPhotoDataUrl = compressedDataUrl;\n        reportPhotoSizeKb = compressedKb;\n        document.getElementById('rep-photo-preview').src = compressedDataUrl;\n        document.getElementById('compression-telemetry').innerHTML =\n          `✅ NFR Auto-Compressed: <strong>${originalKb} KB &rarr; ${compressedKb} KB</strong> (&le; 3MB Limit PASS)`;\n      } else {\n        claimPhotoDataUrl = compressedDataUrl;\n        document.getElementById('claim-photo-preview').src = compressedDataUrl;\n      }\n    };\n    img.src = e.target.result;\n  };\n  reader.readAsDataURL(file);\n}\n\nasync function handleCreateReportSubmit(e) {\n  e.preventDefault();\n  const payload = {\n    username: currentUser.username,\n    type: document.getElementById('report-type-input').value,\n    title: document.getElementById('rep-title').value,\n    category: document.getElementById('rep-category').value,\n    color: document.getElementById('rep-color').value,\n    brand: document.getElementById('rep-brand').value,\n    location: document.getElementById('rep-location').value,\n    date_lost_found: document.getElementById('rep-date').value,\n    description: document.getElementById('rep-description').value,\n    distinguishing_marks: document.getElementById('rep-marks').value,\n    photo_url: reportPhotoDataUrl,\n    image_size_kb: reportPhotoSizeKb,\n    handed_to_office: document.getElementById('rep-handed').checked\n  };\n\n  try {\n    const res = await apiRequest('/reports', {\n      method: 'POST',\n      body: JSON.stringify(payload)\n    });\n\n    const matchCount = res.matchStats?.matchesFound || 0;\n    const matchMs = res.matchStats?.executionTimeMs || 0.8;\n\n    if (matchCount > 0) {\n      showToast(\n        `🎉 Report saved! Automated Match Engine found <strong>${matchCount} match(es)</strong> in <strong>${matchMs} ms</strong> (&lt;3s NFR) &amp; sent match notification!`\n      );\n    } else {\n      showToast(`✅ ${payload.type} report created &amp; scanned in ${matchMs} ms. No match yet—monitoring active.`);\n    }\n\n    document.getElementById('create-report-form').reset();\n    await refreshAllData();\n    switchView(matchCount > 0 ? 'claims' : 'home');\n  } catch (err) {\n    showToast(`❌ Error: ${err.message}`);\n  }\n}\n\n// ==================== 7. OWNERSHIP CLAIMS & BPMN FLOWS ====================\nfunction openClaimModal(foundReportId, lostReportId, foundTitle) {\n  document.getElementById('claim-found-report-id').value = foundReportId;\n  document.getElementById('claim-lost-report-id').value = lostReportId || '';\n  document.getElementById('claim-modal-subtitle').textContent =\n    `Claiming Found Item #${foundReportId}: \"${foundTitle}\". Provide visual proof or serial identifiers.`;\n  document.getElementById('claim-modal').classList.remove('hidden');\n}\n\nfunction closeClaimModal() {\n  document.getElementById('claim-modal').classList.add('hidden');\n}\n\nfunction autofillAhmedClaimProof() {\n  document.getElementById('claim-proof-text').value =\n    'This is my Dell 65W USB-C charger lost in the Engineering Building after my morning lecture. It has a blue velcro cable strap and the serial number on the brick is CN-065W-AH92 (shown in my attached close-up photo).';\n  selectPresetPhoto('charger_proof', 'claim');\n}\n\nasync function handleSubmitClaim(e) {\n  e.preventDefault();\n  const found_report_id = Number(document.getElementById('claim-found-report-id').value);\n  const lost_report_id = document.getElementById('claim-lost-report-id').value\n    ? Number(document.getElementById('claim-lost-report-id').value)\n    : null;\n  const proof_description = document.getElementById('claim-proof-text').value;\n\n  try {\n    await apiRequest('/claims', {\n      method: 'POST',\n      body: JSON.stringify({\n        found_report_id,\n        lost_report_id,\n        username: currentUser.username,\n        proof_description,\n        proof_photo_url: claimPhotoDataUrl\n      })\n    });\n\n    closeClaimModal();\n    showToast('🛡️ Ownership Claim submitted! Status is now <strong>Pending</strong> Admin verification.');\n    await refreshAllData();\n    switchView('claims');\n  } catch (err) {\n    showToast(`❌ ${err.message}`);\n  }\n}\n\nfunction getStatusPillClass(status) {\n  if (status === 'More Proof Requested') return 'MoreProof';\n  if (status === 'Hold Item') return 'Hold';\n  return status;\n}\n\nfunction renderClaimsAndMatchesView() {\n  const matchesEl = document.getElementById('claims-view-matches');\n  if (allMatches.length === 0) {\n    matchesEl.innerHTML = `<div class=\"alert-box\">No automated matches currently active.</div>`;\n  } else {\n    matchesEl.innerHTML = allMatches.map(buildMatchCardHtml).join('');\n  }\n\n  const claimsEl = document.getElementById('student-claims-container');\n  if (allClaims.length === 0) {\n    claimsEl.innerHTML = `<div class=\"alert-box\">No ownership claims submitted yet. Click \"Submit Ownership Claim\" on a Found item or Match above.</div>`;\n    return;\n  }\n\n  claimsEl.innerHTML = allClaims\n    .map((c) => {\n      const pillClass = getStatusPillClass(c.status);\n      const isMyClaim = c.claimant_username.toLowerCase() === currentUser.username.toLowerCase();\n\n      // BPMN Fig. 1: If Admin requested more proof, show button to submit additional proof!\n      let studentActionHtml = '';\n      if (c.status === 'More Proof Requested' && (isMyClaim || currentUser.role === 'admin')) {\n        studentActionHtml = `\n          <div class=\"alert-box alert-warn\" style=\"margin-top:12px;display:flex;align-items:center;justify-content:space-between;gap:12px;\">\n            <div>\n              <strong>🔎 Admin Requested More Proof (BPMN Fig. 1):</strong> \"${escapeHtml(c.admin_feedback)}\"\n            </div>\n            <button class=\"btn btn-warn btn-sm\" onclick=\"openMoreProofModal(${c.id}, '${escapeQuotes(c.admin_feedback)}')\">\n              + Provide Additional Proof\n            </button>\n          </div>\n        `;\n      } else if (c.status === 'Approved') {\n        // BPMN Fig. 5: Student confirms physical item receipt\n        studentActionHtml = `\n          <div class=\"alert-box\" style=\"margin-top:12px;background:#eff6ff;border:1px solid #93c5fd;display:flex;align-items:center;justify-content:space-between;gap:12px;\">\n            <div>\n              <strong>🎉 Claim Approved!</strong> ${escapeHtml(c.admin_feedback)}\n              ${c.receipt_confirmed ? '<br/><span style=\"color:#059669;font-weight:700;\">✓ Student Confirmed Physical Item Receipt (BPMN Fig. 5)</span>' : ''}\n            </div>\n            ${\n              !c.receipt_confirmed\n                ? `<button class=\"btn btn-primary btn-sm\" onclick=\"confirmStudentReceipt(${c.id})\">\n                     ✍️ Confirm Item Receipt (BPMN Fig. 5)\n                   </button>`\n                : ''\n            }\n          </div>\n        `;\n      } else if (c.status === 'Returned') {\n        studentActionHtml = `\n          <div class=\"alert-box\" style=\"margin-top:12px;background:#d1fae5;color:#065f46;border:1px solid #6ee7b7;\">\n            ✅ <strong>Item Status: Returned • Case Status: Resolved.</strong> ${escapeHtml(c.admin_feedback)}\n          </div>\n        `;\n      }\n\n      return `\n        <div class=\"claim-card\">\n          <div class=\"claim-card-header\">\n            <div>\n              <strong>Claim #CLM-${c.id} • ${escapeHtml(c.found_title)}</strong>\n              <span style=\"font-size:12.5px;color:#64748b;margin-left:10px;\">\n                Claimant: <strong>@${escapeHtml(c.claimant_username)}</strong> • Location: ${escapeHtml(c.found_location)}\n              </span>\n            </div>\n            <span class=\"claim-status-pill ${pillClass}\">${escapeHtml(c.status)}</span>\n          </div>\n\n          <div style=\"margin-top:12px;font-size:13.5px;color:#334155;\">\n            <strong>Submitted Proof:</strong> ${escapeHtml(c.proof_description)}\n            ${\n              c.additional_proof_text\n                ? `<div style=\"margin-top:6px;color:#0369a1;\"><strong>Additional Proof Provided:</strong> ${escapeHtml(c.additional_proof_text)}</div>`\n                : ''\n            }\n          </div>\n\n          ${studentActionHtml}\n        </div>\n      `;\n    })\n    .join('');\n}\n\nfunction openMoreProofModal(claimId, adminPrompt) {\n  document.getElementById('more-proof-claim-id').value = claimId;\n  document.getElementById('more-proof-admin-prompt').innerHTML =\n    `<strong>Administrator Request:</strong> \"${escapeHtml(adminPrompt)}\"`;\n  document.getElementById('more-proof-modal').classList.remove('hidden');\n}\n\nfunction closeMoreProofModal() {\n  document.getElementById('more-proof-modal').classList.add('hidden');\n}\n\nasync function handleMoreProofSubmit(e) {\n  e.preventDefault();\n  const claimId = Number(document.getElementById('more-proof-claim-id').value);\n  const additional_proof_text = document.getElementById('more-proof-text').value;\n\n  try {\n    await apiRequest(`/claims/${claimId}/more-proof`, {\n      method: 'POST',\n      body: JSON.stringify({ additional_proof_text })\n    });\n    closeMoreProofModal();\n    showToast('✅ Additional proof submitted! Claim status returned to <strong>Pending</strong> for Admin review.');\n    await refreshAllData();\n  } catch (err) {\n    showToast(`❌ ${err.message}`);\n  }\n}\n\nasync function confirmStudentReceipt(claimId) {\n  try {\n    await apiRequest(`/claims/${claimId}/confirm-receipt`, { method: 'POST', body: JSON.stringify({}) });\n    showToast('✍️ Physical item receipt confirmed (BPMN Fig. 5)! Ready for Admin to mark Returned.');\n    await refreshAllData();\n  } catch (err) {\n    showToast(`❌ ${err.message}`);\n  }\n}\n\n// ==================== 8. ADMIN & DEVOPS ACTIONS (CLAIMS, HANDOVER, MODERATION) ====================\nfunction buildAdminClaimComparisonCard(c, isDarkConsole = false) {\n  const pillClass = getStatusPillClass(c.status);\n  const feedbackInputId = `${isDarkConsole ? 'devops' : 'admin'}-feedback-${c.id}`;\n\n  return `\n    <div class=\"${isDarkConsole ? 'devops-claim-card' : 'claim-card'}\">\n      <div class=\"claim-card-header\">\n        <div>\n          <strong style=\"font-size:15.5px;\">Claim #CLM-${c.id}: ${escapeHtml(c.found_title)}</strong>\n          <span style=\"font-size:12.5px;opacity:0.8;margin-left:10px;\">\n            Claimant: <strong>@${escapeHtml(c.claimant_username)}</strong> | Finder: <strong>@${escapeHtml(c.finder_username)}</strong>\n          </span>\n        </div>\n        <span class=\"claim-status-pill ${pillClass}\">${escapeHtml(c.status)}</span>\n      </div>\n\n      <!-- 3-Column Side-by-Side Comparison (Lost Report vs Unblurred Found Report vs Claimant Proof) -->\n      <div class=\"claim-comparison-grid\">\n        <div class=\"claim-col\">\n          <h5>1. Claimant's Lost Report</h5>\n          ${c.lost_photo_url ? `<img src=\"${c.lost_photo_url}\" alt=\"Lost Report\" />` : ''}\n          <div style=\"font-size:12.5px;\">\n            <strong>${escapeHtml(c.lost_title || 'Direct Claim on Found Listing')}</strong><br/>\n            <span>Marks: ${escapeHtml(c.lost_marks || 'N/A')}</span>\n          </div>\n        </div>\n\n        <div class=\"claim-col\">\n          <h5>2. Found Item (🔓 Unblurred Admin View)</h5>\n          <img src=\"${c.found_photo_url}\" alt=\"Found Unblurred\" />\n          <div style=\"font-size:12.5px;\">\n            <strong>${escapeHtml(c.found_title)} (${escapeHtml(c.found_location)})</strong><br/>\n            <span>Secret Marks: <strong>${escapeHtml(c.found_marks || 'None')}</strong></span>\n          </div>\n        </div>\n\n        <div class=\"claim-col\">\n          <h5>3. Submitted Ownership Proof</h5>\n          <img src=\"${c.proof_photo_url}\" alt=\"Proof Photo\" />\n          <div style=\"font-size:12.5px;\">\n            <strong>Proof:</strong> ${escapeHtml(c.proof_description)}\n            ${\n              c.additional_proof_text\n                ? `<div style=\"margin-top:4px;color:#38bdf8;\"><strong>+ Additional Proof:</strong> ${escapeHtml(c.additional_proof_text)}</div>`\n                : ''\n            }\n          </div>\n        </div>\n      </div>\n\n      <!-- Admin Decision Controls (BPMN Fig. 1 & Fig. 5) -->\n      <div class=\"devops-action-bar\">\n        <input\n          type=\"text\"\n          id=\"${feedbackInputId}\"\n          class=\"${isDarkConsole ? 'devops-feedback-input' : ''}\"\n          style=\"${!isDarkConsole ? 'flex:1;padding:8px 12px;border:1px solid #cbd5e1;border-radius:8px;' : ''}\"\n          placeholder=\"Optional Admin note / reason for requesting more proof...\"\n          value=\"${escapeHtml(c.admin_feedback || '')}\"\n        />\n\n        <div style=\"display:flex;flex-wrap:wrap;gap:8px;\">\n          <button class=\"btn btn-warn btn-sm\" onclick=\"handleAdminClaimAction(${c.id}, 'request_more_proof', '${feedbackInputId}')\">\n            🔎 Request More Proof (BPMN Fig. 1)\n          </button>\n          <button class=\"btn btn-primary btn-sm\" onclick=\"handleAdminClaimAction(${c.id}, 'approve', '${feedbackInputId}')\">\n            ✅ Approve Claim\n          </button>\n          <button class=\"btn btn-danger btn-sm\" onclick=\"handleAdminClaimAction(${c.id}, 'reject', '${feedbackInputId}')\">\n            ❌ Reject\n          </button>\n          <button class=\"btn btn-outline btn-sm\" onclick=\"handleAdminClaimAction(${c.id}, 'verify_identity_no_hold', '${feedbackInputId}')\">\n            ⚠️ ID Failed &rarr; Hold Item (Fig. 5)\n          </button>\n          <button class=\"btn btn-success btn-sm\" onclick=\"handleAdminClaimAction(${c.id}, 'mark_returned', '${feedbackInputId}')\">\n            🤝 Verify ID &amp; Mark Returned (Resolve Case)\n          </button>\n        </div>\n      </div>\n    </div>\n  `;\n}\n\nasync function handleAdminClaimAction(claimId, action, inputId) {\n  const inputEl = document.getElementById(inputId);\n  const admin_feedback = inputEl ? inputEl.value.trim() : '';\n\n  try {\n    await apiRequest(`/claims/${claimId}/admin-action`, {\n      method: 'POST',\n      body: JSON.stringify({ action, admin_feedback })\n    });\n\n    const labels = {\n      request_more_proof: '🔎 Requested More Proof from student (Notification sent!)',\n      approve: '✅ Ownership Claim Approved! Student notified to pick up item.',\n      reject: '❌ Ownership Claim Rejected.',\n      verify_identity_no_hold: '⚠️ Claimant identity check failed -> Physical Item placed on Hold (BPMN Fig. 5).',\n      mark_returned: '🤝 Physical Item Marked Returned &amp; Case Resolved!'\n    };\n    showToast(labels[action] || 'Claim updated.');\n    await refreshAllData();\n  } catch (err) {\n    showToast(`❌ ${err.message}`);\n  }\n}\n\n// BPMN Fig. 4 Suspicious / Duplicate Moderation\nasync function flagReportSuspicious(reportId) {\n  try {\n    await apiRequest(`/reports/${reportId}/moderate`, {\n      method: 'POST',\n      body: JSON.stringify({\n        action: 'flag',\n        reason: 'Flagged by campus user as suspicious or duplicate report.'\n      })\n    });\n    showToast('🚩 Report flagged for Administrator review (BPMN Fig. 4).');\n    await refreshAllData();\n  } catch (err) {\n    showToast(`❌ ${err.message}`);\n  }\n}\n\nasync function handleModerateReport(reportId, action) {\n  try {\n    await apiRequest(`/reports/${reportId}/moderate`, {\n      method: 'POST',\n      body: JSON.stringify({ action })\n    });\n\n    const msgs = {\n      dismiss_flag: '✓ Review Flag Dismissed — Report remains active &amp; Admin Notice sent (BPMN Fig. 4).',\n      modify_or_delete: '🗑️ Suspicious / Duplicate Report deleted &amp; Admin Notice sent (BPMN Fig. 4).',\n      suspend_user: '🚫 Violating User Suspended &amp; Admin Notice sent (BPMN Fig. 4).'\n    };\n    showToast(msgs[action] || 'Moderation applied.');\n    await refreshAllData();\n  } catch (err) {\n    showToast(`❌ ${err.message}`);\n  }\n}\n\nfunction renderAdminWorkspaceView() {\n  const claimsList = document.getElementById('admin-page-claims-list');\n  if (claimsList) {\n    claimsList.innerHTML =\n      allClaims.length === 0\n        ? `<div class=\"alert-box\">No claims submitted yet.</div>`\n        : allClaims.map((c) => buildAdminClaimComparisonCard(c, false)).join('');\n  }\n\n  const suspList = document.getElementById('admin-page-suspicious-list');\n  if (suspList) {\n    const flagged = allReports.filter((r) => r.is_suspicious);\n    suspList.innerHTML =\n      flagged.length === 0\n        ? `<div class=\"alert-box\">No flagged suspicious reports in queue.</div>`\n        : flagged.map((r) => buildModerationCardHtml(r, false)).join('');\n  }\n}\n\nfunction buildModerationCardHtml(r, isDark = true) {\n  return `\n    <div class=\"${isDark ? 'devops-mod-card' : 'claim-card'}\">\n      <div style=\"display:flex;justify-content:space-between;align-items:center;\">\n        <span class=\"type-badge ${r.type}\">#${r.id} • ${r.type}</span>\n        <span style=\"font-size:12px;color:#fbbf24;font-weight:700;\">🚩 FLAGGED SUSPICIOUS</span>\n      </div>\n      <h4 style=\"margin-top:10px;font-size:16px;\">${escapeHtml(r.title)}</h4>\n      <p style=\"font-size:12.5px;opacity:0.85;margin-top:4px;\">\n        Posted by <strong>@${escapeHtml(r.username)}</strong> at ${escapeHtml(r.location)}\n      </p>\n      <p style=\"font-size:12.5px;margin-top:8px;padding:8px;background:rgba(245,158,11,0.15);border-radius:8px;\">\n        <strong>Flag Reason:</strong> ${escapeHtml(r.suspicious_reason || 'Suspicious / duplicate listing')}\n      </p>\n\n      <div style=\"margin-top:14px;display:flex;flex-wrap:wrap;gap:8px;\">\n        <button class=\"btn btn-success btn-sm\" onclick=\"handleModerateReport(${r.id}, 'dismiss_flag')\">\n          ✓ Valid: Dismiss Flag\n        </button>\n        <button class=\"btn btn-warn btn-sm\" onclick=\"handleModerateReport(${r.id}, 'modify_or_delete')\">\n          🗑️ Modify / Delete Report\n        </button>\n        <button class=\"btn btn-danger btn-sm\" onclick=\"handleModerateReport(${r.id}, 'suspend_user')\">\n          🚫 Violates: Suspend @${escapeHtml(r.username)}\n        </button>\n      </div>\n    </div>\n  `;\n}\n\n// ==================== 9. DARK-BLUE DEVOPS & ADMIN CONSOLE ====================\nfunction toggleDevOpsModal(forceState) {\n  const overlay = document.getElementById('devops-overlay');\n  const shouldOpen = typeof forceState === 'boolean' ? forceState : overlay.classList.contains('hidden');\n  if (shouldOpen) {\n    overlay.classList.remove('hidden');\n    refreshAllData();\n  } else {\n    overlay.classList.add('hidden');\n  }\n}\n\nfunction switchDevOpsTab(tabName) {\n  document.querySelectorAll('.devops-tab').forEach((btn) => {\n    btn.classList.toggle('active', btn.dataset.dtab === tabName);\n  });\n  document.getElementById('dpanel-claims').classList.toggle('hidden', tabName !== 'claims');\n  document.getElementById('dpanel-moderation').classList.toggle('hidden', tabName !== 'moderation');\n  document.getElementById('dpanel-telemetry').classList.toggle('hidden', tabName !== 'telemetry');\n}\n\nfunction renderDevOpsConsole() {\n  if (!appHealth) return;\n\n  // 1. Render 1-Click Persona Switcher Pills\n  const switcherEl = document.getElementById('devops-user-switcher');\n  if (switcherEl) {\n    const users = appHealth.users || [];\n    switcherEl.innerHTML = users\n      .map((u) => {\n        const isCurrent = currentUser && currentUser.username.toLowerCase() === u.username.toLowerCase();\n        const roleIcon = u.role === 'admin' ? '🛡️' : '🎓';\n        return `\n          <button\n            class=\"devops-btn ${isCurrent ? 'active-persona' : ''}\"\n            onclick=\"devopsSwitchUser('${escapeQuotes(u.username)}')\"\n          >\n            ${roleIcon} @${escapeHtml(u.username)} ${u.status === 'suspended' ? '(🚫 Suspended)' : ''}\n          </button>\n        `;\n      })\n      .join('');\n  }\n\n  // 2. Render Badges\n  document.getElementById('dtab-claims-count').textContent = allClaims.length;\n  const flaggedReports = allReports.filter((r) => r.is_suspicious);\n  document.getElementById('dtab-mod-count').textContent = flaggedReports.length;\n\n  // 3. Render Claims inside Dark-Blue DevOps Panel\n  const devopsClaimsEl = document.getElementById('devops-claims-container');\n  if (devopsClaimsEl) {\n    devopsClaimsEl.innerHTML =\n      allClaims.length === 0\n        ? `<div class=\"devops-panel-intro\">No ownership claims currently in SQLite. Use the Scenario Loader above or submit a claim as Ahmed!</div>`\n        : allClaims.map((c) => buildAdminClaimComparisonCard(c, true)).join('');\n  }\n\n  // 4. Render Suspicious Reports inside Dark-Blue DevOps Panel\n  const devopsModEl = document.getElementById('devops-moderation-container');\n  if (devopsModEl) {\n    devopsModEl.innerHTML =\n      flaggedReports.length === 0\n        ? `<div class=\"devops-panel-intro\">No suspicious reports currently flagged. You can click the 🚩 button on any campus listing to test the BPMN Fig. 4 moderation workflow!</div>`\n        : flaggedReports.map((r) => buildModerationCardHtml(r, true)).join('');\n  }\n\n  // 5. Render NFR Status & SQLite Users Table & Logs\n  const nfrListEl = document.getElementById('devops-nfr-list');\n  if (nfrListEl && appHealth.nfr) {\n    nfrListEl.innerHTML = `\n      <li>\n        <span>⚡ Automated Match Performance (&le; 3,000 ms)</span>\n        <strong style=\"color:#34d399;\">${appHealth.nfr.lastMatchLatencyMs} ms (PASS)</strong>\n      </li>\n      <li>\n        <span>🔒 Privacy &amp; Found-Item Photo Blur</span>\n        <strong style=\"color:#34d399;\">ACTIVE (PASS)</strong>\n      </li>\n      <li>\n        <span>🖼️ Image Compression &amp; Storage (&le; 3.0 MB)</span>\n        <strong style=\"color:#34d399;\">ENFORCED (PASS)</strong>\n      </li>\n      <li>\n        <span>🛡️ Role-Based Access Control (Student vs Admin)</span>\n        <strong style=\"color:#34d399;\">STRICT (PASS)</strong>\n      </li>\n      <li>\n        <span>📱 Mobile-Responsive Usability</span>\n        <strong style=\"color:#34d399;\">RESPONSIVE GRID (PASS)</strong>\n      </li>\n    `;\n  }\n\n  const usersWrap = document.getElementById('devops-users-table-wrap');\n  if (usersWrap && appHealth.users) {\n    usersWrap.innerHTML = `\n      <table style=\"width:100%;font-size:12.5px;border-collapse:collapse;\">\n        <thead>\n          <tr style=\"text-align:left;color:#7dd3fc;border-bottom:1px solid rgba(56,189,248,0.2);\">\n            <th style=\"padding:6px;\">ID</th>\n            <th style=\"padding:6px;\">Username</th>\n            <th style=\"padding:6px;\">Role</th>\n            <th style=\"padding:6px;\">Status</th>\n            <th style=\"padding:6px;\">Action</th>\n          </tr>\n        </thead>\n        <tbody>\n          ${appHealth.users\n            .map(\n              (u) => `\n            <tr style=\"border-bottom:1px solid rgba(255,255,255,0.06);\">\n              <td style=\"padding:6px;\">#${u.id}</td>\n              <td style=\"padding:6px;font-weight:700;\">@${escapeHtml(u.username)}</td>\n              <td style=\"padding:6px;\">${escapeHtml(u.role)}</td>\n              <td style=\"padding:6px;color:${u.status === 'active' ? '#34d399' : '#f87171'};font-weight:700;\">\n                ${escapeHtml(u.status)}\n              </td>\n              <td style=\"padding:6px;\">\n                <button class=\"devops-btn\" style=\"padding:3px 8px;font-size:11px;\" onclick=\"toggleUserSuspend(${u.id})\">\n                  ${u.status === 'active' ? 'Suspend' : 'Restore'}\n                </button>\n              </td>\n            </tr>\n          `\n            )\n            .join('')}\n        </tbody>\n      </table>\n    `;\n  }\n\n  const logsEl = document.getElementById('devops-logs-terminal');\n  if (logsEl && appHealth.recentLogs) {\n    logsEl.innerHTML = appHealth.recentLogs\n      .map(\n        (l) => `\n        <div class=\"log-line\">\n          <span style=\"color:#94a3b8;\">[${new Date(l.created_at).toLocaleTimeString()}]</span>\n          <strong style=\"color:#fbbf24;\">[${escapeHtml(l.event_type)}]</strong>\n          <span>${escapeHtml(l.summary)}</span>\n          <span style=\"color:#34d399;\">(${l.latency_ms}ms)</span>\n        </div>\n      `\n      )\n      .join('');\n  }\n}\n\nasync function devopsSwitchUser(username) {\n  try {\n    const data = await apiRequest('/devops/switch-user', {\n      method: 'POST',\n      body: JSON.stringify({ username })\n    });\n    currentUser = data.user;\n    localStorage.setItem('reclaim_user', JSON.stringify(currentUser));\n    showToast(`⚡ DevOps Switched Active Persona to <strong>@${currentUser.username}</strong> (${currentUser.role.toUpperCase()})`);\n    await enterAppShell();\n  } catch (err) {\n    showToast(`❌ ${err.message}`);\n  }\n}\n\nasync function loadScenario(mode) {\n  try {\n    const res = await apiRequest('/devops/scenario', {\n      method: 'POST',\n      body: JSON.stringify({ mode })\n    });\n    showToast(`🎬 ${res.message}`);\n    await refreshAllData();\n  } catch (err) {\n    showToast(`❌ ${err.message}`);\n  }\n}\n\nasync function toggleUserSuspend(userId) {\n  try {\n    await apiRequest('/devops/toggle-user-status', {\n      method: 'POST',\n      body: JSON.stringify({ userId })\n    });\n    showToast('🔄 Updated user account status in SQLite.');\n    await refreshAllData();\n  } catch (err) {\n    showToast(`❌ ${err.message}`);\n  }\n}\n\n// ==================== 10. NOTIFICATIONS DRAWER ====================\nfunction toggleNotificationsDrawer(forceState) {\n  const drawer = document.getElementById('notifications-drawer');\n  const shouldOpen = typeof forceState === 'boolean' ? forceState : drawer.classList.contains('hidden');\n  drawer.classList.toggle('hidden', !shouldOpen);\n}\n\nfunction renderNotificationsDrawer() {\n  const list = document.getElementById('notifications-list');\n  if (!list) return;\n  if (userNotifications.length === 0) {\n    list.innerHTML = `<div class=\"alert-box\">No notifications for @${escapeHtml(currentUser?.username || '')} yet.</div>`;\n    return;\n  }\n\n  list.innerHTML = userNotifications\n    .map(\n      (n) => `\n      <div class=\"notif-item ${n.is_read ? '' : 'unread'}\">\n        <div style=\"display:flex;justify-content:space-between;font-size:11px;color:#64748b;margin-bottom:4px;\">\n          <strong>${escapeHtml(n.type)}</strong>\n          <span>${new Date(n.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</span>\n        </div>\n        <h5>${escapeHtml(n.title)}</h5>\n        <p>${escapeHtml(n.message)}</p>\n      </div>\n    `\n    )\n    .join('');\n}\n\nasync function markAllNotificationsRead() {\n  if (!currentUser) return;\n  await apiRequest('/notifications/read-all', {\n    method: 'POST',\n    body: JSON.stringify({ username: currentUser.username })\n  });\n  await refreshAllData();\n}\n\n// Helpers\nfunction escapeHtml(str) {\n  return String(str ?? '')\n    .replace(/&/g, '&amp;')\n    .replace(/</g, '&lt;')\n    .replace(/>/g, '&gt;')\n    .replace(/\"/g, '&quot;');\n}\n\nfunction escapeQuotes(str) {\n  return String(str ?? '').replace(/'/g, \"\\\\'\").replace(/\"/g, '&quot;');\n}\n\n"};